/* _applySettingsToConv extracted to frontend/src/runtime/core/conv_apply_settings.js
 * (pt_3879f00e sub-part 2 slice 5). Loaded via the migrated module graph BEFORE both
 * conversations.js and cross_tab_sync.js so every call site — 8 here + 1
 * in cross_tab_sync's _handleConvNotifyPush — resolves the bare name at
 * runtime via the shared bundle scope. */
/* hydrateSidebarFromCache extracted to frontend/src/runtime/core/conv_hydrate_cache.js
