/* ═══════════════════════════════════════════════════════════════════
   endpoint_turn_projection.js — pure Flow/Endpoint chat-turn identity

   Live SSE and degraded polling consume the same backend metadata through
   this projection so role lanes, dedup keys and persisted markers cannot
   diverge by transport.
   ═══════════════════════════════════════════════════════════════════ */
function projectEndpointChatTurn(source, phase, iteration) {
  source = source || {};
  var normalizedPhase = phase || source.phase
    || source.endpointPhase || 'working';
  var rawIteration = iteration;
  if (rawIteration === undefined || rawIteration === null) {
    rawIteration = source.iteration;
  }
  if (rawIteration === undefined || rawIteration === null) {
    rawIteration = source.endpointIteration;
  }
  var normalizedIteration = Number(rawIteration) || 0;
  var virtualUser = normalizedPhase === 'reviewing'
    && source.turnRole === 'virtual_user';
  var fields = {};
  if (normalizedPhase === 'planning') {
    fields._isEndpointPlanner = true;
  } else if (normalizedPhase === 'reviewing' && virtualUser) {
    fields._isVirtualUser = true;
    fields._msgId = source.vuMsgId || '';
    if (source.autopilotRunId) {
      fields._autopilotRunId = source.autopilotRunId;
    }
  } else if (normalizedPhase === 'reviewing') {
    fields._isEndpointReview = true;
    fields._epIteration = normalizedIteration;
    fields._epApproved = false;
  } else {
    fields._epIteration = normalizedIteration;
  }
  return {
    phase: normalizedPhase,
    iteration: normalizedIteration,
    virtualUser: virtualUser,
    turnKey: virtualUser
      ? 'vu:' + (source.vuMsgId || normalizedIteration)
      : normalizedPhase + ':' + normalizedIteration,
    streamRole: normalizedPhase === 'reviewing'
      ? (virtualUser ? 'autopilot' : 'critic')
      : (normalizedPhase === 'planning' ? 'planner' : 'worker'),
    fields: fields,
  };
}

function applyEndpointChatTurn(message, projection) {
  Object.keys((projection && projection.fields) || {}).forEach(function (key) {
    message[key] = projection.fields[key];
  });
  return message;
}

function endpointChatTurnMatches(message, projection) {
  if (!message || !projection) return false;
  if (projection.virtualUser) {
    return !!(message._isVirtualUser && projection.fields._msgId
      && message._msgId === projection.fields._msgId);
  }
  return !!(message._isEndpointReview
    && message._epIteration === projection.iteration);
}

function finalizeEndpointChatUserTurn(message, nextPhase, isStuck) {
  if (!message) return message;
  if (!message._isVirtualUser) {
    message._epApproved = nextPhase === 'stop';
    message._epNextPhase = nextPhase;
  }
  message._isStuck = !!isStuck;
  message.done = true;
  return message;
}

function endpointFlowProjectionLabel(source) {
  return source && source.flowProjection === 'autopilot'
    ? 'Autopilot'
    : (source && source.flowProjection === 'flow' ? 'Flow' : 'Endpoint');
}

