  if (producer) {
    return `continue-${_continueHeaderPart(conv.id)}-${_continueHeaderPart(producer)}`;
  }
  const rounds = getToolRoundsFromMsg(assistantMsg) || [];
  const lastRound = rounds.length ? rounds[rounds.length - 1] : {};
