if (typeof window !== "undefined") {
  runtimeScope._wireConvHistoryRewritePush = _wireConvHistoryRewritePush;
  runtimeScope._onConvSyncPush = _onConvSyncPush;          // exposed for tests
  runtimeScope._applyHistoryRewrite = _applyHistoryRewrite; // exposed for tests
}

