      + (icons.gear || '') + ' ' + _escape(label) + '</span>'
      + '<button type="button" class="orch-icon-btn orch-inspector-close" title="'
      + _escape(_translate('orch.tip.close')) + '" aria-label="'
      + _escape(_translate('orch.tip.close')) + '">'
      + (icons.reject || '') + '</button></div>';
