    '<span class="pm-opt-icon">' + _pvIconSvg(icon) + '</span>' +
    '<span class="pm-opt-title">' + _pvEsc(title) + '</span>' +
    '<span class="pm-opt-sub">' + _pvEsc(sub) + '</span></button>';
