      canonicalDirty: 'Canonical 有脏文件', dirtyNote: '这些文件仍然可见，但尚未进入 candidate 或 stable。',
      modified: '修改', deleted: '删除', untracked: '未跟踪',
      server: '当前运行服务', servesStable: '正在运行 stable',
      servesCandidate: '正在运行 candidate', servesLocal: '启动时加载了本地脏源码',
      serverUnknown: '与 refs 的关系无法确认', worktrees: 'Git worktrees',
      prunable: '可清理', gates: '门禁', builtInOnly: '仅内置检查',
      integrationTests: '已配置集成测试命令', stableTests: '已配置 stable 测试命令',
      prune: '清理失效记录', confirmPrune: '清理那些目录已经不存在的 Git worktree 元数据？',
      unregistered: '未登记的 worktrees', unregisteredHint: 'Git 能看到，但不属于当前自动集成队列。',
