/* ── project STATE subset MOVED to project_state.js (CORE, Epic-E pt_3879f00e sub-7, 2026-08-01): _scanPollTimer, toggleAutoApply/_updateAutoApplyUI, _saveConvProjectPath … _restoreConvProject, _projectBarFolders, clearProject, _applyProjectData/_startScanPoll/_stopScanPoll, _updateProjectUI/_deriveConvPathsFromState/_roToggleSeq/toggleProjectBarReadOnly, loadProjectStatus. This file is now the DEFERRED panel; it calls those at RUNTIME via window scope (core loads first). ── */
let _pendingWriteApprovals = new Map();

async function resolveWriteApproval(approvalId, approved) {
  try {
    const data = await Api.project.writeApproval(approvalId, approved);
    if (!data || data.error) {
      debugLog("Approval failed: " + ((data && data.error) || "Unknown"), "warn");
      return;
    }
    debugLog(
      `Write ${approved ? "approved" : "rejected"}: ${approvalId.slice(0, 16)}`,
      approved ? "success" : "warn",
    );
  } catch (e) {
    debugLog("Approval error: " + e.message, "error");
  }
}

// ══════════════════════════════════════════════════════
