async function _submitHumanGuidanceResponse(guidanceId, responseText) {
  try {
    const conv = (typeof getActiveConv === 'function') ? getActiveConv() : null;
    const data = await Api.chat.humanResponse(guidanceId, responseText,
                                              conv && conv.id);
    if (!data || data.error) {
      debugLog("Human guidance submit failed: " + ((data && data.error) || "Unknown"), "warn");
      if (typeof showToast === 'function')
        showToast("Failed to submit response", "error");
      return false;
    }
    debugLog(`Human guidance answered: ${guidanceId}`, "success");
    return true;
  } catch (e) {
    debugLog("Human guidance error: " + e.message, "error");
    if (typeof showToast === 'function')
      showToast("Network error submitting response", "error");
    return false;
  }
}

async function submitHumanGuidanceFreeText(guidanceId) {
  const textarea = document.getElementById(`hg-input-${guidanceId}`);
  if (!textarea) return;
  const text = textarea.value.trim();
  if (!text) {
    textarea.classList.add('hg-shake');
    setTimeout(() => textarea.classList.remove('hg-shake'), 500);
    return;
  }
  const card = textarea.closest('.hg-card');
  if (card) card.classList.add('hg-submitting');

  // ★ Auto-translate CN→EN: if autoTranslate is ON and text contains Chinese,
  //   translate before sending to backend — same as sendMessage() flow.
  const conv = getActiveConv();
  const _hgAutoTrans = convAutoTranslate(conv);
  const hasChinese = /[\u4e00-\u9fff\u3400-\u4dbf]/.test(text);
  let finalText = text;

  if (_hgAutoTrans && hasChinese) {
    // Show translating state on the submit button
    const submitBtn = card?.querySelector('.hg-submit-btn');
    if (submitBtn) {
      submitBtn.disabled = true;
      submitBtn.innerHTML = '<span class="hg-spinner"></span> ' + escapeHtml(t('project.hgTranslating'));
    }
    try {
      console.log(`[HG-Submit] Auto-translating user response CN→EN (${text.length} chars)`);
      finalText = await _callTranslateAPI(text, 'English', 'Chinese');
      console.log(`[HG-Submit] ✓ Translated: ${text.length}→${finalText.length} chars`);
    } catch (e) {
      console.warn(`[HG-Submit] Translation failed, sending original: ${e.message}`);
      if (typeof showToast === 'function')
        showToast(t('project.hgTranslateFailed'), 'warning');
      finalText = text; // fallback to original
    }
    if (submitBtn) {
      submitBtn.disabled = false;
      submitBtn.innerHTML = '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><line x1="22" y1="2" x2="11" y2="13"/><polygon points="22 2 15 22 11 13 2 9 22 2"/></svg> ' + escapeHtml(t('project.hgSubmit'));
    }
  }

  const ok = await _submitHumanGuidanceResponse(guidanceId, finalText);
  if (!ok && card) card.classList.remove('hg-submitting');
  if (ok) _collapseHgRoundAfterSubmit(guidanceId, text);
}

async function submitHumanGuidanceChoice(guidanceId, choiceLabel) {
  // Find and highlight the selected option card
  const allBtns = document.querySelectorAll(`button.hg-option-card[data-gid="${guidanceId}"]`);
  allBtns.forEach(btn => {
    btn.classList.remove('hg-selected');
    if (btn.dataset.label === choiceLabel) btn.classList.add('hg-selected');
    btn.disabled = true;
  });
  const card = document.querySelector(`button.hg-option-card[data-gid="${guidanceId}"]`)?.closest('.hg-card');
  if (card) card.classList.add('hg-submitting');
  const ok = await _submitHumanGuidanceResponse(guidanceId, choiceLabel);
  if (!ok) {
    allBtns.forEach(btn => { btn.disabled = false; btn.classList.remove('hg-selected'); });
    if (card) card.classList.remove('hg-submitting');
  }
  if (ok) _collapseHgRoundAfterSubmit(guidanceId, choiceLabel);
}

/* translateHumanGuidanceInput removed — auto-translation is now fully automatic:
 * - EN→CN: LLM question & options translated on arrival (_autoTranslateHumanGuidance)
 * - CN→EN: User's free-text reply translated on submit (submitHumanGuidanceFreeText)
 */

/**
 * ★ Immediately collapse the HG interactive card after successful submission.
 * Sets local round status to "submitted" so the card collapses to a compact line
 * ("✓ 已回答") instead of staying grayed-out until the server sends tool_result.
 * When tool_result arrives, it will overwrite status to "done" as normal.
 */
function _collapseHgRoundAfterSubmit(guidanceId, responseText) {
  const conv = getActiveConv();
  if (!conv) return;
  const assistantMsg = [...conv.messages].reverse().find(m => m.role === 'assistant');
  if (!assistantMsg || !assistantMsg.toolRounds) return;
  const round = assistantMsg.toolRounds.find(r => r.guidanceId === guidanceId);
  if (!round) return;
  // Transition: awaiting_human → submitted (immediately collapses card)
  round.status = 'submitted';
  round._hgUserResponse = responseText;
  round.guidanceId = null; // prevent re-rendering the interactive card
  console.log(`[HG] ✓ Card collapsed: round=${round.roundNum}, response="${responseText.slice(0, 60)}"`);
  // Update sidebar: conversation no longer awaiting human (amber dot → streaming dot)
  renderConversationList();
  // Force-refresh streaming UI to show collapsed state (§7: the pipeline
  // reads the document directly — the stamp above is already visible).
  if (typeof twUpdate === 'function') twUpdate(activeConvId);
}

// ── Multi-path folder state for the modal ──
let _mpFolders = []; // array of path strings being edited in the modal
let _mpReadOnly = new Set(); // subset of _mpFolders the user marked read-only
// Mirror of the badges currently painted in the project bar ({path, readOnly}),
// so the bar's click-to-toggle handler can look an entry up by index.

function _syncFoldersFromState() {
  /* Build _mpFolders from projectState (single source of truth).
   * ORDER IS SEMANTIC: index 0 IS the primary root (star + `root` badge, sent
   * to the backend as the primary in setPaths). The primary is pushed FIRST
   * here so the root always lands at the very top of the Workspace list —
   * extra roots follow in server order. The drag-to-reorder gesture
   * (_mpReorder) is the ONLY thing allowed to change which path is index 0. */
  _mpFolders = [];
  _mpReadOnly = new Set();
  if (projectState.path) {
    _mpFolders.push(projectState.path);
    if (projectState.readOnly) _mpReadOnly.add(projectState.path);
  }
  if (projectState.extraRoots && projectState.extraRoots.length) {
    for (const r of projectState.extraRoots) {
      const p = typeof r === 'string' ? r : r.path;
      if (p && !_mpFolders.includes(p)) {
        _mpFolders.push(p);
        if (r && typeof r === 'object' && r.readOnly) _mpReadOnly.add(p);
      }
    }
  }
}

function _mpToggleReadOnly(index) {
  const p = _mpFolders[index];
  if (!p) return;
  if (_mpReadOnly.has(p)) _mpReadOnly.delete(p);
  else _mpReadOnly.add(p);
  _mpRenderTags();
}

function openProjectModal() {
  _syncFoldersFromState();
  _mpRenderTags();
  _updateProjectModalStatus();
  _recentFilter = "";
  const _recentInput = document.getElementById("recentSearchInput");
  if (_recentInput) _recentInput.value = "";
  renderRecentProjects();
  document.getElementById("projectModal").classList.add("open");
  // Tell the full-page chat-drop handler (main.js) to stand down so a file
  // dropped onto the folder browser is SAVED to disk, not attached to chat.
  runtimeScope._tofuProjectModalOpen = true;
  // Default mobile view to Browse on each open (no-op on desktop).
  pmMobileTab("browse");
  // Docked browser: populate it from the primary folder (or home) on open.
  browseDirectory(_mpFolders.length ? _mpFolders[0] : "~");
  _attachFolderDropZone();
  _attachMpReorder();
  setTimeout(() => document.getElementById("mpPathInput").focus(), 100);
}

function closeProjectModal() {
  document.getElementById("projectModal").classList.remove("open");
  runtimeScope._tofuProjectModalOpen = false;
}

/* ── Mobile segmented tab toggle (Browse / Workspace) ──
 * Desktop shows both panes side-by-side; on narrow screens the .pm-body
 * is driven by a data-pm-view attribute so only one pane is visible at a
 * time, giving each the full viewport height instead of two cramped halves. */
function pmMobileTab(view) {
  const modal = document.querySelector('#projectModal .pm-workbench');
  if (!modal) return;
  modal.setAttribute('data-pm-view', view);
  modal.querySelectorAll('.pm-mtab').forEach((b) => {
    b.classList.toggle('active', b.getAttribute('data-pm-tab') === view);
  });
}

/* ── Multi-path tag rendering ── */
function _mpRenderTags() {
  const container = document.getElementById("mpFolderTags");
  const countEl = document.getElementById("mpFolderCount");
  if (countEl) countEl.textContent = _mpFolders.length ? `${_mpFolders.length}` : '';
  const mCountEl = document.getElementById("pmMobileCount");
  if (mCountEl) mCountEl.textContent = _mpFolders.length ? `${_mpFolders.length}` : '';
  if (!_mpFolders.length) {
    container.innerHTML = '<div class="mp-empty-hint">No folders yet — type a path or pick one from the browser.</div>';
    return;
  }
  const _t = (typeof t === "function") ? t : (k) => k;
  const _gripTip = escapeHtml(_t("pm.dragReorder"));
  container.innerHTML = _mpFolders.map((p, i) => {
    const parts = p.split('/').filter(Boolean);
    const name = parts[parts.length - 1] || p;
    const short = parts.length > 2 ? '…/' + parts.slice(-2).join('/') : p;
    const isPrimary = i === 0;
    const isRO = _mpReadOnly.has(p);
    // Lock (read-only) / pencil (writable) toggle. Click flips the access
    // policy for this root — sent to the backend as readOnlyPaths.
    const lockIcon = isRO
      ? '<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="11" width="18" height="11" rx="2"/><path d="M7 11V7a5 5 0 0 1 10 0v4"/></svg>'
      : '<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 20h9"/><path d="M16.5 3.5a2.12 2.12 0 0 1 3 3L7 19l-4 1 1-4Z"/></svg>';
    // 6-dot grip: the drag affordance. The WHOLE row is draggable (the grip is
    // the visual hint), except its buttons — see _attachMpReorder's dragstart.
    const grip = '<span class="mp-row-grip icon-box" title="' + _gripTip + '" aria-hidden="true"><svg width="11" height="15" viewBox="0 0 10 16" fill="currentColor"><circle cx="3" cy="3" r="1.35"/><circle cx="8" cy="3" r="1.35"/><circle cx="3" cy="8" r="1.35"/><circle cx="8" cy="8" r="1.35"/><circle cx="3" cy="13" r="1.35"/><circle cx="8" cy="13" r="1.35"/></svg></span>';
    return `<div class="mp-row${isPrimary ? ' mp-row-primary' : ''}${isRO ? ' mp-row-readonly' : ''}" draggable="true" data-mp-idx="${i}" title="${escapeHtml(p)}">
      ${grip}
      <span class="mp-row-icon">${isPrimary
        ? '<svg width="15" height="15" viewBox="0 0 24 24" fill="#f59e0b" stroke="#f59e0b" stroke-width="1.5" stroke-linejoin="round"><polygon points="12 2 15 9 22 9 16.5 13.5 18.5 21 12 16.5 5.5 21 7.5 13.5 2 9 9 9"/></svg>'
        : '<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" opacity="0.55"><path d="M22 19a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h5l2 3h9a2 2 0 0 1 2 2z"/></svg>'}</span>
      <span class="mp-row-text">
        <span class="mp-row-name">${escapeHtml(name)}</span>
        <span class="mp-row-path">${escapeHtml(short)}</span>
      </span>
      ${isPrimary ? '<span class="mp-row-badge">root</span>' : ''}
      ${isRO ? '<span class="mp-row-badge mp-row-badge-ro">read-only</span>' : ''}
      <button class="mp-row-lock${isRO ? ' active' : ''}" draggable="false" data-tofu-action="_mpToggleReadOnly(${i})" title="${isRO ? 'Read-only — click to allow edits' : 'Writable — click to make read-only'}">${lockIcon}</button>
      <button class="mp-row-remove" draggable="false" data-tofu-action="_mpRemove(${i})" title="Remove">
        <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
      </button>
    </div>`;
  }).join('');
}

/* ── Drag-to-reorder the Workspace list ──────────────────────────────────
 * ORDER IS SEMANTIC: `_mpFolders[0]` is the PRIMARY root (star + `root`
 * badge; sent to the backend as the primary in setPaths, the rest as extra
 * roots). So dragging a folder to the top IS the "promote to root" gesture —
 * there is no separate control, and the root is always the top row.
 *
 * The rows are rebuilt wholesale by _mpRenderTags (innerHTML), so the
 * listeners are DELEGATED onto the stable #mpFolderTags container and wired
 * exactly once (_mpReorderAttached), mirroring the image-chip reorder in
 * upload.js. */
var _mpReorderAttached = false;
var _mpDragFrom = null;

/** Move `from` → `to` within _mpFolders and repaint. `to` is the final index
 *  the entry should occupy. No-ops on out-of-range or same-position moves.
 *  Returns true when the array actually changed (drives the tests). */
function _mpReorder(from, to) {
  const n = _mpFolders.length;
  if (!Number.isInteger(from) || !Number.isInteger(to)) return false;
  if (from < 0 || from >= n) return false;
  const dest = Math.max(0, Math.min(n - 1, to));
  if (dest === from) return false;
  const moved = _mpFolders.splice(from, 1)[0];
  _mpFolders.splice(dest, 0, moved);
  _mpRenderTags();
  return true;
}

/** Row element under the pointer, plus whether the pointer sits in its TOP
 *  half (insert before) or bottom half (insert after). */
function _mpRowAt(target, clientY) {
  const row = target && target.closest ? target.closest('.mp-row[data-mp-idx]') : null;
  if (!row) return null;
  const idx = parseInt(row.dataset.mpIdx, 10);
  if (!Number.isInteger(idx)) return null;
  const rect = row.getBoundingClientRect();
  const before = rect.height ? (clientY - rect.top) < rect.height / 2 : true;
  return { row, idx, before };
}

/** Translate a hover position into the destination index for _mpReorder. */
function _mpDropIndex(from, hit) {
  let to = hit.before ? hit.idx : hit.idx + 1;
  if (from < to) to -= 1;   // removing `from` first shifts everything after it
  return to;
}

function _mpClearDropMarks() {
  document.querySelectorAll('.mp-row.mp-drop-before, .mp-row.mp-drop-after')
    .forEach((el) => el.classList.remove('mp-drop-before', 'mp-drop-after'));
}

function _mpMarkDrop(hit) {
  _mpClearDropMarks();
  if (!hit) return;
  hit.row.classList.add(hit.before ? 'mp-drop-before' : 'mp-drop-after');
}

function _mpEndDrag() {
  _mpClearDropMarks();
  document.querySelectorAll('.mp-row.mp-row-dragging')
    .forEach((el) => el.classList.remove('mp-row-dragging'));
  _mpDragFrom = null;
}

function _attachMpReorder() {
  if (_mpReorderAttached) return;
  const list = document.getElementById('mpFolderTags');
  if (!list) return;
  _mpReorderAttached = true;

  // ── Desktop: HTML5 drag-and-drop ──
  list.addEventListener('dragstart', (e) => {
    // Buttons keep their click semantics — never start a drag from one.
    if (e.target.closest && e.target.closest('button')) { e.preventDefault(); return; }
    const hit = _mpRowAt(e.target, e.clientY);
    if (!hit) return;
    _mpDragFrom = hit.idx;
    hit.row.classList.add('mp-row-dragging');
    if (e.dataTransfer) {
      e.dataTransfer.effectAllowed = 'move';
      // Firefox refuses to start a drag without payload.
      try { e.dataTransfer.setData('text/plain', String(hit.idx)); } catch (_e) { /* ignore */ }
    }
  });

  list.addEventListener('dragover', (e) => {
    if (_mpDragFrom === null) return;   // a file drag — not ours, let it pass
    e.preventDefault();                  // accept → the OS shows the move cursor
    e.stopPropagation();
    if (e.dataTransfer) e.dataTransfer.dropEffect = 'move';
    _mpMarkDrop(_mpRowAt(e.target, e.clientY));
  });

  list.addEventListener('dragleave', (e) => {
    if (_mpDragFrom === null) return;
    if (e.target === list && !list.contains(/** @type {Node} */(e.relatedTarget))) _mpClearDropMarks();
  });

  list.addEventListener('drop', (e) => {
    if (_mpDragFrom === null) return;
    // Swallow it: releasing over the modal must never reach the page-level
    // file-drop handler nor paste the text/plain index anywhere.
    e.preventDefault();
    e.stopPropagation();
    const from = _mpDragFrom;
    const hit = _mpRowAt(e.target, e.clientY);
    _mpEndDrag();
    if (hit) _mpReorder(from, _mpDropIndex(from, hit));
  });

  list.addEventListener('dragend', () => { _mpEndDrag(); });

  /* ── Touch: HTML5 DnD does not fire on touch devices, and the modal has a
   * dedicated mobile Workspace pane. Dragging starts from the GRIP only so a
   * finger anywhere else still scrolls the list. touchmove is non-passive
   * because it must preventDefault to stop the page scrolling mid-drag. */
  list.addEventListener('touchstart', (e) => {
    const touch = e.touches && e.touches[0];
    if (!touch || !e.target.closest || !e.target.closest('.mp-row-grip')) return;
    const hit = _mpRowAt(e.target, touch.clientY);
    if (!hit) return;
    _mpDragFrom = hit.idx;
    hit.row.classList.add('mp-row-dragging');
  }, { passive: true });

  list.addEventListener('touchmove', (e) => {
    if (_mpDragFrom === null) return;
    const touch = e.touches && e.touches[0];
    if (!touch) return;
    e.preventDefault();   // hold the page still while repositioning
    const under = document.elementFromPoint(touch.clientX, touch.clientY);
    _mpMarkDrop(under ? _mpRowAt(under, touch.clientY) : null);
  }, { passive: false });

  const _touchEnd = (e) => {
    if (_mpDragFrom === null) return;
    const touch = (e.changedTouches && e.changedTouches[0]) || null;
    const from = _mpDragFrom;
    const under = touch ? document.elementFromPoint(touch.clientX, touch.clientY) : null;
    const hit = under ? _mpRowAt(under, touch.clientY) : null;
    _mpEndDrag();
    if (hit) _mpReorder(from, _mpDropIndex(from, hit));
  };
  list.addEventListener('touchend', _touchEnd);
  list.addEventListener('touchcancel', () => { _mpEndDrag(); });
}


function mpAddFolder() {
  const input = document.getElementById("mpPathInput");
  const p = input.value.trim();
  if (!p) return;
  if (_mpFolders.includes(p)) {
    input.value = '';
    input.focus();
    return;
  }
  _mpFolders.push(p);
  input.value = '';
  _mpRenderTags();
  input.focus();
}

function _mpRemove(index) {
  const removed = _mpFolders.splice(index, 1);
  if (removed && removed[0]) _mpReadOnly.delete(removed[0]);
  _mpRenderTags();
}

function _mpBrowseForAdd() {
  const el = document.getElementById("folderBrowser");
  const wasHidden = el.hidden;
  el.hidden = !wasHidden;
  if (wasHidden) {
    const inputPath = document.getElementById("mpPathInput").value.trim();
    browseDirectory(inputPath || (_mpFolders.length ? _mpFolders[0] : "~"));
  }
}

function _mpSelectBrowsed() {
  const path = document.getElementById("mpPathInput").value.trim();
  if (path) {
    if (!_mpFolders.includes(path)) {
      _mpFolders.push(path);
      _mpRenderTags();
    }
    document.getElementById("mpPathInput").value = '';
    document.getElementById("folderBrowser").hidden = true;
  }
}

/* ★ Auto-enable the project-oriented execution modes when the user turns
 * Project mode ON. Swarm + Autopilot default OFF for a bare chat (see
 * core.js / _resetToolsToDefaults), and are switched on here as a
 * convenience the moment a workspace is attached — the modes most useful for
 * multi-step work on a real project.
 *
 * Guardrails:
 *  - Only flips a mode that is currently OFF (never fights the user if they
 *    already turned one on manually).
 *  - Respects the autopilot ⇄ endpoint/flow mutual exclusion: if Endpoint
 *    Mode or a custom Flow is already active, we do NOT force Autopilot on top
 *    (that pairing would double-loop — see toggleAutopilot).
 *  - Persists the new state via _saveConvToolState so it survives conv switch. */
function _autoEnableProjectModes() {
  let changed = false;
  if (typeof swarmEnabled !== 'undefined' && !swarmEnabled
      && typeof _applySwarmUI === 'function') {
    _applySwarmUI(true);
    changed = true;
  }
  const _endpointOn = (typeof endpointEnabled !== 'undefined') && endpointEnabled;
  const _flowOn = (typeof activeFlow !== 'undefined') && !!activeFlow;
  if (typeof autopilotEnabled !== 'undefined' && !autopilotEnabled
      && !_endpointOn && !_flowOn
      && typeof _applyAutopilotUI === 'function') {
    _applyAutopilotUI(true);
    changed = true;
  }
  if (changed) {
    if (typeof _saveConvToolState === 'function') _saveConvToolState();
    /* ★ Refresh the toolbar submenu count badges (e.g. 模式 "2") so they
     * reflect the newly-enabled modes — _applySwarmUI/_applyAutopilotUI only
     * repaint their own toggle+badge, not the aggregate count (mirrors
     * _resetToolsToDefaults / _restoreConvToolState). */
    if (typeof updateSubmenuCounts === 'function') updateSubmenuCounts();
    if (typeof debugLog === 'function') {
      debugLog('Project mode on — Swarm + Autopilot auto-enabled', 'info');
    }
  }
}

/* ★ mpApplyFolders — the "Set Project" action.
   First path → primary project; remaining → extra roots.

   Optimistic UI: paint the project bar + close the modal immediately
   from the user's typed paths, then fire /api/project/set_paths in the
   background and reconcile when it returns.  The backend response
   canonicalises paths (~ expansion, abs path) and adds crossDC info,
   so reconciliation may rewrite the bar — that's fine and expected.
   On failure we revert to the previous state and reopen the modal. */
async function mpApplyFolders() {
  if (!_mpFolders.length) return;
  // ★ Ensure we have an active conversation
  if (!activeConvId) {
    const now = Date.now();
    const conv = {
      id: generateId(), title: "New Chat", messages: [],
      createdAt: now, updatedAt: now, activeTaskId: null, projectPath: "",
    };
    /* ★ FIX: Auto-assign to active folder when creating a conv from project modal.
     * Without this, the conv stays uncategorized even though the user selected
     * a folder tab before clicking New Chat → project tool → send message. */
    const _curFolderId = typeof getActiveFolderId === 'function' ? getActiveFolderId() : null;
    if (_curFolderId) conv.folderId = _curFolderId;
    conversations.unshift(conv);
    activeConvId = conv.id;
    /* ★ Persist immediately — the conv only exists in memory until synced.
     * saveConversations sorts + broadcasts; the conv will reach the server
     * once the user sends a message (via syncConversationToServer). */
    saveConversations(conv.id);
    renderConversationList();
  }

  const folders = _mpFolders.slice();
  const primary = folders[0];
  const extras = folders.slice(1);
  const readOnly = folders.filter(p => _mpReadOnly.has(p));

  // ── Optimistic apply: paint UI from typed paths and close the modal ──
  const _prevProjectState = { ...projectState, extraRoots: (projectState.extraRoots || []).slice() };
  _applyProjectData({
    path: primary,
    readOnly: _mpReadOnly.has(primary),
    extraRoots: extras.map(p => ({ path: p, readOnly: _mpReadOnly.has(p) })),
    crossDC: null,
  });
  _saveConvProjectPath(primary, extras, readOnly);
  for (const p of folders) {
    if (p) saveRecentProject(p);
  }
  closeProjectModal();
  const nExtras = extras.length;
  const nRO = readOnly.length;
  debugLog(`Project set: ${primary}` + (nExtras ? ` + ${nExtras} extra folder(s)` : '') + (nRO ? ` (${nRO} read-only)` : ''), "success");
  /* ★ Attaching a project IS the Studio tier. Promote the capability dial so
   * the UI + derived flags stay truthful. NOTE (owner-directed 2026-07-19):
   * the tier is DECOUPLED from execution strategy — attaching a project no
   * longer auto-enables Swarm / Autopilot (those are orthogonal B-axis modes
   * the user turns on explicitly). _autoEnableProjectModes is retired from
   * this path. */
  if (typeof onProjectAttached === 'function') onProjectAttached();
  else if (typeof _saveConvToolState === 'function') _saveConvToolState();

  // ── Reconcile with the server in the background ──
  try {
    const resp = await Api.project.setPaths(folders, readOnly);
    const data = resp ? await resp.json().catch(() => ({})) : {};
    if (!resp || !resp.ok) throw new Error(data.error || "Failed");
    _applyProjectData(data);
    _saveConvProjectPath(data.path, _mpFolders.slice(1), readOnly);
  } catch (e) {
    // Revert the optimistic state and reopen the modal so the user can fix it.
    projectState = _prevProjectState;
    _saveConvProjectPath(_prevProjectState.path || "",
                         (_prevProjectState.extraRoots || []).map(r => typeof r === 'string' ? r : r.path));
    _updateProjectUI();
    /* ★ Studio ⟺ a project is attached. Rolling back to a state with NO
     * project must demote the dial as well — the optimistic promotion was
     * already persisted by onProjectAttached, so without this the conv is
     * left in the poisoned "Studio + no project" shape (durably so, since
     * the promotion now saves immediately). onProjectCleared repaints AND
     * persists the fallback. When the previous state DID have a project the
     * tier stays Studio — still truthful. */
    if (!_prevProjectState.path && typeof onProjectCleared === 'function') onProjectCleared();
    document.getElementById("projectModal").classList.add("open");
    const statusEl = document.getElementById("projectModalStatus");
    if (statusEl) {
      statusEl.innerHTML = `<div style="color:var(--error-text);font-size:12px">${escapeHtml(e.message)}</div>`;
    }
    debugLog(`Project set failed: ${e.message}`, "error");
  }
}

// Kept for backward compat / quick-set from recent list
async function setProject(pathOverride) {
  const path = pathOverride || (document.getElementById("mpPathInput") ? document.getElementById("mpPathInput").value.trim() : "");
  if (!path) return;
  _mpFolders = [path];
  _mpRenderTags();
  await mpApplyFolders();
}

// ── Recent Project Paths (server-side persistence) ──

function saveRecentProject(path) {
  if (!path) return;
  Api.project.recentSave(path)
    .catch(e => debugLog(`[saveRecentProject] ${e.message}`, 'warn'));
}

let _recentProjects = [];
let _recentFilter = "";

async function renderRecentProjects() {
  const container = document.getElementById("recentProjectPaths");
  const listEl = document.getElementById("recentPathsList");
  if (!container || !listEl) return;
  let list = [];
  try {
    const data = await Api.project.recentList();
    if (data) {
      list = Array.isArray(data) ? data : data.projects || [];
    }
  } catch {}
  _recentProjects = list;
  if (list.length === 0) {
    container.hidden = true;
    return;
  }
  container.hidden = false;
  _renderRecentList();
}

// Basename of a path (last non-empty segment).
function _recentName(path) {
  const parts = String(path).split("/").filter(Boolean);
  return parts[parts.length - 1] || path;
}

// Highlight the matched substring of `text` (case-insensitive), HTML-escaping
// both the surrounding text and the match so a path can't inject markup.
function _recentHighlight(text, query) {
  const safe = escapeHtml(text);
  if (!query) return safe;
  const idx = text.toLowerCase().indexOf(query.toLowerCase());
  if (idx < 0) return safe;
  const before = escapeHtml(text.slice(0, idx));
  const match = escapeHtml(text.slice(idx, idx + query.length));
  const after = escapeHtml(text.slice(idx + query.length));
  return `${before}<mark class="recent-hl">${match}</mark>${after}`;
}

function _renderRecentList() {
  const listEl = document.getElementById("recentPathsList");
  const countEl = document.getElementById("recentCount");
  const clearBtn = document.getElementById("recentSearchClear");
  if (!listEl) return;
  const q = _recentFilter.trim();
  const filtered = q
    ? _recentProjects.filter(
        (item) => item.path.toLowerCase().includes(q.toLowerCase()),
      )
    : _recentProjects;
  if (countEl) countEl.textContent = q ? `${filtered.length}/${_recentProjects.length}` : String(_recentProjects.length);
  if (clearBtn) clearBtn.hidden = !q;
  if (filtered.length === 0) {
    const _t = (typeof t === "function") ? t : (k) => k;
    const msg = q ? _t("pm.recentNoMatch") : _t("pm.recentEmpty");
    listEl.innerHTML = `<div class="recent-paths-empty">${escapeHtml(msg)}</div>`;
    return;
  }
  listEl.innerHTML = filtered
    .map((item) => {
      const name = _recentName(item.path);
      return `<div class="recent-path-item" data-tofu-action="selectRecentProject('${escapeHtml(item.path)}')" title="${escapeHtml(item.path)}">
         <span class="recent-path-text">
           <span class="recent-path-name">${_recentHighlight(name, q)}</span>
           <span class="recent-path-full">${_recentHighlight(item.path, q)}</span>
         </span>
         ${item.count > 1 ? `<span class="recent-path-count">×${item.count}</span>` : ""}
       </div>`;
    })
    .join("");
}

function _filterRecentProjects(value) {
  _recentFilter = value || "";
  _renderRecentList();
}

function _clearRecentSearch() {
  _recentFilter = "";
  const input = document.getElementById("recentSearchInput");
  if (input) {
    input.value = "";
    input.focus();
  }
  _renderRecentList();
}

function selectRecentProject(path) {
  if (!path) return;
  // Add the recent project path into the multi-path list and apply
  if (!_mpFolders.includes(path)) {
    _mpFolders.push(path);
    _mpRenderTags();
  }
  // Switch the left-hand folder browser to that item's location so the user
  // sees where it lives (breadcrumb + listing reflect the selected path).
  browseDirectory(path);
}

async function clearRecentProjects() {
  await Api.project.recentClear().catch(() => {});
  renderRecentProjects();
}

async function rescanProject() {
  if (!projectState.active) return;
  try {
    const resp = await Api.project.rescan();
    const data = resp ? await resp.json().catch(() => ({})) : {};
    if (resp && resp.ok) {
      _applyProjectData(data);
      debugLog("Project refreshed", "success");
    }
  } catch (e) {
    debugLog("Rescan failed: " + e.message, "warn");
  }
}

async function undoConvModifications(msgIdx) {
  if (!projectState.active) return;
  const conv = getActiveConv();
  if (!conv) return;
  const msg = conv.messages[msgIdx];
  if (!msg || msg.role !== "assistant" || !msg.modifiedFiles) return;
  const count = msg.modifiedFiles;
  if (
    !await showConfirm(
      t('project.undoTurnConfirm', { count: count }),
      { danger: true },
    )
  )
    return;
  try {
    // ★ Per-round undo: prefer taskId (specific to this round), fallback to convId.
    //   ALWAYS pin the conversation's own project path so undo targets the
    //   session that recorded the change — NOT whichever project is globally
    //   active in the UI (which may differ when another conversation switched
    //   projects mid-task). Without this, undo silently no-ops (undone=0).
    const body = msg._taskId
      ? { taskId: msg._taskId }
      : { convId: conv.id };
    const convProjectPath = _getConvProjectPath(conv);
    if (convProjectPath) body.projectPath = convProjectPath;
    const resp = await Api.project.undo(body);
    const data = resp ? await resp.json().catch(() => ({})) : {};
    if (resp && resp.ok && data.ok) {
      if (typeof showToast === 'function') {
        showToast('↩️', 'Undo Complete',
          `Reverted ${data.undone} file change${data.undone !== 1 ? 's' : ''}` +
          (data.failed ? ` (${data.failed} failed)` : ''),
          4000);
      }
      // ★ Stash the round's file list + the pin needed to redo it, THEN clear
      //   the live counter fields. Undo deletes the round's server-side record,
      //   so redo must resupply taskId + the conversation's projectPath (the
      //   route never falls back to the globally-active UI project). Keeping
      //   modifiedFiles/modifiedFileList cleared keeps sidebar badges and the
      //   render fingerprint honest — the "undone → Redo" bar renders off the
      //   stashed _undoneFileList instead.
      if (msg._taskId) {
        msg._undoneFileList = Array.isArray(msg.modifiedFileList) ? msg.modifiedFileList : [];
        msg._undoneTaskId = msg._taskId;
        msg._undoneProjectPath = _getConvProjectPath(conv) || '';
      }
      // Clear the modifiedFiles flag on this message
      msg.modifiedFiles = 0;
      msg.modifiedFileList = null;
      saveConversations(conv.id);
      // Re-render the message to swap the undo button for a redo button
      const el = document.getElementById(`msg-${msgIdx}`);
      if (el) el.outerHTML = renderMessage(msg, msgIdx);
      _lastRenderedFingerprint = _convRenderFingerprint(conv);
      // Re-scan project to update file counts
      rescanProject();
    } else {
      debugLog("Undo failed: " + (data.error || "unknown error"), "warn");
    }
  } catch (e) {
    debugLog("Undo failed: " + e.message, "warn");
  }
}

async function undoAllModifications() {
  if (!projectState.active) return;
  if (
    !await showConfirm(
      t('project.undoAllConfirm'),
      { danger: true },
    )
  )
    return;
  try {
    // ★ Pin the conversation's own project so undo-all targets the session
    //   that recorded the changes — NOT whichever project is globally active
    //   in the UI. Mirrors per-round undo; keeps behaviour independent of UI
    //   focus when conversations edit different projects concurrently.
    const conv0 = getActiveConv();
    const body = {};
    const convProjectPath = _getConvProjectPath(conv0);
    if (convProjectPath) body.projectPath = convProjectPath;
    const resp = await Api.project.undoAll(body);
    const data = resp ? await resp.json().catch(() => ({})) : {};
    if (resp && resp.ok && data.ok) {
      if (typeof showToast === 'function') {
        showToast('↩️', 'Undo All Complete',
          `Reverted ${data.undone} file change${data.undone !== 1 ? 's' : ''}` +
          (data.failed ? ` (${data.failed} failed)` : ''),
          5000);
      }
      // Clear modifiedFiles on all messages in all conversations
      for (const c of conversations) {
        for (const m of c.messages) {
          if (m.modifiedFiles) {
            m.modifiedFiles = 0;
            m.modifiedFileList = null;
          }
        }
      }
      saveConversations(activeConvId);
      // Re-render current chat
      const conv = getActiveConv();
      if (conv) runtimeScope.ConvView.replaceAll(conv.id);
      rescanProject();
    } else {
      debugLog("Undo all failed: " + (data.error || "unknown error"), "warn");
    }
  } catch (e) {
    debugLog("Undo all failed: " + e.message, "warn");
  }
}

async function redoConvModifications(msgIdx) {
  if (!projectState.active) return;
  const conv = getActiveConv();
  if (!conv) return;
  const msg = conv.messages[msgIdx];
  // Only meaningful on a round that was undone (carries the stash below).
  if (!msg || msg.role !== "assistant" || !msg._undoneTaskId) return;
  try {
    // ★ Redo requires the round's taskId AND an explicit projectPath pin: undo
    //   deleted the round's record, so the route resolves the project from the
    //   pin, never the globally-active UI project (mirrors the undo contract;
    //   covered by test_project_undo_redo_concurrent_resolution.py).
    const body = { taskId: msg._undoneTaskId };
    if (msg._undoneProjectPath) body.projectPath = msg._undoneProjectPath;
    const resp = await Api.project.redo(body);
    const data = resp ? await resp.json().catch(() => ({})) : {};
    if (resp && resp.ok && data.ok) {
      if (typeof showToast === 'function') {
        showToast('↪️', 'Redo Complete',
          `Re-applied ${data.redone} file change${data.redone !== 1 ? 's' : ''}`,
          4000);
      }
      // Restore the live counter fields from the stash, clear the undone marks.
      const restored = Array.isArray(msg._undoneFileList) ? msg._undoneFileList : [];
      msg.modifiedFileList = restored;
      msg.modifiedFiles = restored.length;
      delete msg._undoneFileList;
      delete msg._undoneTaskId;
      delete msg._undoneProjectPath;
      saveConversations(conv.id);
      // Re-render the message to swap the redo button back for undo.
      const el = document.getElementById(`msg-${msgIdx}`);
      if (el) el.outerHTML = renderMessage(msg, msgIdx);
      _lastRenderedFingerprint = _convRenderFingerprint(conv);
      rescanProject();
    } else {
      debugLog("Redo failed: " + (data.error || "unknown error"), "warn");
    }
  } catch (e) {
    debugLog("Redo failed: " + e.message, "warn");
  }
}


function _updateProjectModalStatus() {
  const el = document.getElementById("projectModalStatus");
  if (!el) return;
  if (!projectState.active) { el.innerHTML = ""; return; }
  const total = _mpFolders.length;
  el.innerHTML = `<div style="font-size:12px;color:#34d399;margin-bottom:12px">
    ✓ ${total} folder${total > 1 ? 's' : ''} active
  </div>`;
}

// ══════════════════════════════════════════════════════
//  ★ Folder Browser
// ══════════════════════════════════════════════════════

let _browseState = { path: "", dirs: [], parent: null, showHidden: false };

function toggleFolderBrowser() {
  const el = document.getElementById("folderBrowser");
  const wasHidden = el.hidden;
  el.hidden = !wasHidden;
  if (wasHidden) {
    const inputPath = document.getElementById("mpPathInput").value.trim();
    browseDirectory(inputPath || "~");
  }
}

async function browseDirectory(path) {
  const listEl = document.getElementById("browseList");
  listEl.innerHTML =
    '<div class="fb-state"><div class="fb-state-spinner"></div><span>Loading…</span></div>';
  _renderRemoteDevicesSection();
  try {
    const data = await Api.project.browse(path, _browseState.showHidden);
    if (!data) {
      listEl.innerHTML = '<div class="fb-state fb-state-error"><span>Browse failed</span></div>';
      return;
    }
    if (data.error) {
      listEl.innerHTML =
        '<div class="fb-state fb-state-error"><span>' +
        escapeHtml(data.error) +
        "</span></div>";
      return;
    }
    _browseState.path = data.path;
    _browseState.dirs = data.dirs || [];
    _browseState.parent = data.parent;
    _browseState.filesCount = data.filesCount || 0;

    _renderBreadcrumb(data.path);
    document.getElementById("browseBackBtn").disabled = !data.parent;

    _renderBrowseList();
  } catch (e) {
    listEl.innerHTML =
      '<div class="fb-state fb-state-error"><span>' +
      escapeHtml(e.message) +
      "</span></div>";
  }
}

/* Render the browser's directory rows from _browseState (extracted seam —
   the fetch path AND the optimistic delete-row repaint both ride it, so the
   row HTML exists exactly once). */
function _renderBrowseList() {
  const listEl = document.getElementById("browseList");
  if (!listEl) return;
  if (_browseState.dirs.length === 0) {
    listEl.innerHTML =
      '<div class="fb-state"><span>No subdirectories' +
      (_browseState.filesCount ? " · " + _browseState.filesCount + " files" : "") +
      "</span></div>";
    return;
  }

  listEl.innerHTML = _browseState.dirs
      .map(function (d) {
        var badge = d.hasCode
          ? '<span class="folder-code-badge">code</span>'
          : "";
        var hidden = d.hidden ? " folder-hidden" : "";
        var added = _mpFolders.includes(d.path) ? " folder-added" : "";
        var items =
          d.itemCount > 0
            ? '<span class="folder-item-count">' +
              (d.itemCount > 100 ? "100+" : d.itemCount) +
              "</span>"
            : "";
        var safePath = d.path.replace(/\\/g, "\\\\").replace(/'/g, "\\'");
        var icon = d.hasCode
          ? '<svg class="fi-folder" width="16" height="16" viewBox="0 0 24 24" fill="rgba(245,158,11,0.14)" stroke="#f59e0b" stroke-width="1.8" stroke-linejoin="round"><path d="M22 19a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h5l2 3h9a2 2 0 0 1 2 2z"/></svg>'
          : '<svg class="fi-folder" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round" opacity="0.55"><path d="M22 19a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h5l2 3h9a2 2 0 0 1 2 2z"/></svg>';
        var safeName = d.name.replace(/\\/g, "\\\\").replace(/'/g, "\\'");
        return (
          '<div class="folder-item' + hidden + added +
          '" data-dir-path="' + escapeHtml(d.path) + '"' +
          ' data-tofu-action="browseDirectory(\'' + safePath + '\')" title="Open ' + escapeHtml(d.name) + '">' +
          '<span class="folder-icon">' + icon + "</span>" +
          '<span class="folder-name">' + escapeHtml(d.name) + "</span>" +
          badge + items +
          '<button class="folder-del-btn" data-tofu-action="event.stopPropagation();mpDeleteFolder(\'' + safePath + '\',\'' + safeName + '\')" title="Delete folder">' +
          '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg>' +
          '</button>' +
          '<button class="folder-add-btn" data-tofu-action="event.stopPropagation();mpAddBrowsedPath(\'' + safePath + '\')" title="Add to workspace">' +
          '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>' +
          '</button>' +
          '<svg class="folder-chevron" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="9 18 15 12 9 6"/></svg>' +
          "</div>"
        );
      })
      .join("");
}

/* Render a clickable breadcrumb trail (VS Code style) for the current path.
   Each crumb navigates to that ancestor on click. */
function _renderBreadcrumb(path) {
  const el = document.getElementById("browseCrumbs");
  if (!el) return;
  const parts = path.split("/").filter(Boolean);
  const isAbs = path.startsWith("/");
  const crumbs = [];
  // Root crumb: "/" for absolute paths, else the first segment.
  const rootPath = isAbs ? "/" : (parts[0] || path);
  crumbs.push(
    '<button class="pm-crumb pm-crumb-root" data-tofu-action="browseDirectory(\'' +
    rootPath.replace(/\\/g, "\\\\").replace(/'/g, "\\'") +
    '\')" title="' + escapeHtml(rootPath) + '">' +
    '<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 9l9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/></svg>' +
    '</button>'
  );
  let walk = isAbs ? "" : parts[0] || "";
  const startIdx = isAbs ? 0 : 1;
  for (let i = startIdx; i < parts.length; i++) {
    walk = walk + "/" + parts[i];
    const full = isAbs ? walk : walk.replace(/^\//, "");
    const last = i === parts.length - 1;
    const safe = full.replace(/\\/g, "\\\\").replace(/'/g, "\\'");
    crumbs.push('<span class="pm-crumb-sep">/</span>');
    crumbs.push(
      '<button class="pm-crumb' + (last ? ' pm-crumb-current' : '') +
      '" data-tofu-action="browseDirectory(\'' + safe + '\')" title="' + escapeHtml(full) + '">' +
      escapeHtml(parts[i]) + '</button>'
    );
  }
  el.innerHTML = crumbs.join("");
  // Scroll to the end so the deepest crumb is visible.
  el.scrollLeft = el.scrollWidth;
}

function selectFolderItem(el, path) {
  document.querySelectorAll(".folder-item.selected").forEach(function (e) {
    e.classList.remove("selected");
  });
  el.classList.add("selected");
  document.getElementById("mpPathInput").value = path;
}

/* Add a folder shown in the browser straight into the workspace list.
   Re-renders the current directory so the row's "added" state updates. */
function mpAddBrowsedPath(path) {
  if (path && !_mpFolders.includes(path)) {
    _mpFolders.push(path);
    _mpRenderTags();
    browseDirectory(_browseState.path);
  }
}

/* RWA P4b-2a(拍板 6A):目录浏览弹窗顶部「远程设备」分组。
   在线 agent 的每个共享根一行,点 + 把伪路径加入工作区
   (与本地文件夹同一套 _mpFolders/保存/持久化机制);离线 agent 灰显、
   不可加。无 agent 时整段隐藏(本地使用零干扰)。 */
async function _renderRemoteDevicesSection() {
  const sec = document.getElementById('remoteDevicesSection');
  if (!sec || typeof Api === 'undefined' || !Api.desktop) return;
  let data = null;
  try {
    data = await Api.desktop.devices();
  } catch (e) {
    data = null;
  }
  const agents = (data && data.agents) || [];
  if (!agents.length) {
    sec.innerHTML = '';
    sec.style.display = 'none';
    return;
  }
  let html = '<div class="remote-devices-title">' +
    escapeHtml(t('devices.remoteGroup')) + '</div>';
  agents.forEach(function (a) {
    const roots = a.share_roots || [];
    const online = !!a.online;
    html += '<div class="remote-agent-row' +
      (online ? '' : ' remote-agent-offline') + '">' +
      '<span class="remote-agent-name">' +
      (online ? '● ' : '○ ') + escapeHtml(a.name || a.agent_id) +
      ' <span class="stg-dim">' + escapeHtml(a.platform || '') + '</span></span>';
    roots.forEach(function (r) {
      const pseudo = 'remote:' + a.agent_id + ':' + (r.name || r.path);
      html += '<span class="remote-root-row">' +
        '<span class="remote-root-name">' +
        escapeHtml(r.name || r.path) + '</span>';
      if (online) {
        html += '<button class="remote-root-add" data-pseudo="' +
          escapeHtml(pseudo) + '" title="' + escapeHtml(pseudo) + '">+</button>';
      }
      html += '</span>';
    });
    html += '</div>';
  });
  sec.innerHTML = html;
  sec.style.display = '';
  sec.querySelectorAll('.remote-root-add').forEach(function (btn) {
    btn.onclick = function (ev) {
      ev.stopPropagation();
      mpAddBrowsedPath(btn.getAttribute('data-pseudo'));
    };
  });
}

function browseParent() {
  if (_browseState.parent) browseDirectory(_browseState.parent);
}

/* Create a new sub-folder inside the directory the browser is currently
   showing, then refresh so the new folder appears in the list. */
async function mpNewFolder() {
  const parent = _browseState.path;
  if (!parent) return;
  const name = await showPrompt(t('folder.createInHint', { dir: parent }), {
    title: t('folder.createTitle'),
    placeholder: t('folder.namePh'),
    okText: t('folder.create'),
  });
  if (name == null) return; // cancelled
  const clean = String(name).trim();
  if (!clean) return;
  try {
    const resp = await Api.project.mkdir(parent, clean);
    const data = resp ? await resp.json().catch(() => ({})) : {};
    if (resp && resp.ok && data.ok) {
      if (typeof showToast === 'function') showToast(t('folder.created'), 'success');
      browseDirectory(parent);
    } else {
      await showAlert((data && data.error) || t('folder.createFailed'),
        { title: t('folder.createFailed') });
    }
  } catch (e) {
    await showAlert(e.message || t('folder.createFailed'),
      { title: t('folder.createFailed') });
  }
}

/* Delete a folder shown in the browser (moved to a recoverable trash bin),
   then refresh the current directory. */
async function mpDeleteFolder(path, name) {
  if (!path) return;
  if (!await showConfirm(
    t('folder.deleteDirConfirm', { name: name || path }) + '\n' +
    t('folder.deleteDirHint'),
    { danger: true, title: t('folder.deleteTitle') })) return;
  /* ★ INSTANT-UI (owner directive 2026-07-31, pt_e8a166d6a4b64123): the row
   *   leaves the browser list AND the staged workspace tag disappears in the
   *   SAME task as the confirm — the old code awaited the rmdir RTT first.
   *   The deletion lands in .tofu_trash (recoverable by design), so the
   *   optimistic removal is the safest in the app: on failure we re-fetch
   *   the directory (server truth restores the row) and re-stage the tag. */
  const _rowIdx = _browseState.dirs.findIndex((d) => d.path === path);
  if (_rowIdx >= 0) {
    _browseState.dirs.splice(_rowIdx, 1);
    _renderBrowseList();
  }
  const _stagedIdx = _mpFolders.indexOf(path);
  const _wasStaged = _stagedIdx !== -1;
  if (_wasStaged) { _mpFolders.splice(_stagedIdx, 1); _mpRenderTags(); }
  try {
    const resp = await Api.project.rmdir(path);
    const data = resp ? await resp.json().catch(() => ({})) : {};
    if (resp && resp.ok && data.ok) {
      if (typeof showToast === 'function') showToast(t('folder.deleted'), 'success');
      _mpReadOnly.delete(path);
      browseDirectory(_browseState.path);
    } else {
      throw new Error((data && data.error) || t('folder.deleteFailed'));
    }
  } catch (e) {
    /* ★ Rollback: re-stage the workspace tag at its original index, then
     *   re-fetch the list so the row comes back from server truth. */
    if (_wasStaged) {
      _mpFolders.splice(Math.min(_stagedIdx, _mpFolders.length), 0, path);
      _mpRenderTags();
    }
    browseDirectory(_browseState.path);
    await showAlert(e.message || t('folder.deleteFailed'),
      { title: t('folder.deleteFailed') });
  }
}

function toggleHiddenDirs() {
  _browseState.showHidden = !_browseState.showHidden;
  var btn = document.getElementById("browseHiddenBtn");
  btn.classList.toggle("active", _browseState.showHidden);
  btn.title = _browseState.showHidden ? "Hide hidden dirs" : "Show hidden dirs";
  browseDirectory(_browseState.path);
}

function selectBrowsedFolder() {
  // Docked browser: add the current open directory to the workspace list.
  // Single-click now navigates, so the footer button targets the dir the
  // browser is currently showing. The browser stays open for more adds.
  const input = document.getElementById("mpPathInput");
  const path = input.value.trim() || _browseState.path;
  if (path && !_mpFolders.includes(path)) {
    _mpFolders.push(path);
    _mpRenderTags();
    browseDirectory(_browseState.path);
  }
  input.value = "";
}

// ══════════════════════════════════════════════════════
//  ★ Apply Code to File
// ══════════════════════════════════════════════════════

let _applyPendingCode = "";

function openApplyModal(btn) {
  if (!projectState.active) {
    debugLog("No project set — cannot apply code", "warn");
    return;
  }
  var pre = btn.closest("pre");
  var code = pre.querySelector("code");
  if (!code) return;
  _applyPendingCode = code.textContent;

  var detectedPath = _detectFilePath(pre, code);
  document.getElementById("applyFilePath").value = detectedPath || "";

  var lines = _applyPendingCode.split("\n");
  var preview =
    lines.length > 20
      ? lines.slice(0, 10).join("\n") +
        "\n  … (" +
        (lines.length - 20) +
        " more lines) …\n" +
        lines.slice(-10).join("\n")
      : _applyPendingCode;
  document.getElementById("applyPreview").innerHTML =
    '<div style="font-size:11px;color:var(--text-tertiary);margin-bottom:4px">' +
    lines.length +
    " lines · " +
    _applyPendingCode.length.toLocaleString() +
    " chars</div>" +
    '<pre style="max-height:300px;overflow:auto;font-size:12px;padding:8px;background:var(--bg-primary);border-radius:6px;margin:0"><code>' +
    escapeHtml(preview) +
    "</code></pre>";

  document.getElementById("applyStatus").innerHTML = "";
  document.getElementById("applyConfirmBtn").disabled = false;
  document.getElementById("applyConfirmBtn").textContent = "Write File";
  document.getElementById("applyModal").classList.add("open");
  setTimeout(function () {
    document.getElementById("applyFilePath").focus();
  }, 100);
}

function closeApplyModal() {
  document.getElementById("applyModal").classList.remove("open");
  _applyPendingCode = "";
}

function _detectFilePath(preEl, codeEl) {
  var firstLine = (codeEl.textContent || "").split("\n")[0] || "";
  var fileCommentMatch = firstLine.match(
    /^(?:#|\/\/|\/\*|<!--)\s*(?:file|path|filename):\s*(.+?)(?:\s*(?:\*\/|-->))?$/i,
  );
  if (fileCommentMatch) return fileCommentMatch[1].trim();
  var node = preEl.previousElementSibling;
  for (var i = 0; i < 3 && node; i++) {
    var text = node.textContent || "";
    var pathMatch = text.match(/`([^`]+\.\w{1,10})`\s*[:：]?\s*$/);
    if (
      pathMatch &&
      (pathMatch[1].indexOf("/") >= 0 || pathMatch[1].indexOf(".") >= 0)
    ) {
      return pathMatch[1];
    }
    var fileMatch = text.match(
      /(?:file|文件)[：:]\s*[`"']?([^\s`"']+\.\w{1,10})/i,
    );
    if (fileMatch) return fileMatch[1];
    node = node.previousElementSibling;
  }
  return "";
}

async function confirmApplyCode() {
  var path = document.getElementById("applyFilePath").value.trim();
  if (!path) {
    document.getElementById("applyStatus").innerHTML =
      '<div style="color:var(--error-text);font-size:12px;margin-top:8px">Please enter a file path</div>';
    return;
  }
  if (!_applyPendingCode) return;

  var btn = document.getElementById("applyConfirmBtn");
  btn.disabled = true;
  btn.textContent = "Writing…";
  document.getElementById("applyStatus").innerHTML = "";

  try {
    var data = await Api.project.write(path, _applyPendingCode);
    if (data && data.ok) {
      var action = data.created ? "Created" : "Updated";
      document.getElementById("applyStatus").innerHTML =
        '<div style="color:#34d399;font-size:12px;margin-top:8px">' +
        action +
        ": " +
        escapeHtml(data.path) +
        " (" +
        data.lines +
        " lines)</div>";
      debugLog(
        "Applied code to " +
          data.path +
          " (" +
          data.lines +
          " lines, " +
          (data.created ? "created" : "updated") +
          ")",
        "success",
      );
      setTimeout(function () {
        closeApplyModal();
      }, 1200);
    } else {
      throw new Error(data.error || "Write failed");
    }
  } catch (e) {
    document.getElementById("applyStatus").innerHTML =
      '<div style="color:var(--error-text);font-size:12px;margin-top:8px">' +
      escapeHtml(e.message) +
      "</div>";
    btn.disabled = false;
    btn.textContent = "Write File";
  }
}


/* ═══════════════════════════════════════════════════════
   Drag-and-drop files INTO a project folder (folder browser)
   ═══════════════════════════════════════════════════════
   Distinct from the full-page chat drop (main.js), which attaches files to
   the next MESSAGE. Dropping onto the folder browser SAVES the raw bytes to
   disk inside the attached workspace (binary-safe, sandboxed, undoable).

   The full-page chat overlay lives at document level (z-index 200); this
   handler is bound directly to #folderBrowser and runs in the CAPTURE phase +
   stopPropagation so a file dropped on the browser is saved to disk and NOT
   also attached to chat. main.js additionally skips its overlay while the
   project modal is open (see _tofuProjectModalOpen). */
var _folderDropAttached = false;

/** Resolve which directory a drop landed on: a specific folder row's path,
 *  else the directory currently shown in the browser. Returns '' if unknown. */
function _folderDropTargetDir(target) {
  var row = target && target.closest ? target.closest('.folder-item[data-dir-path]') : null;
  if (row && row.dataset.dirPath) return row.dataset.dirPath;
  return (typeof _browseState !== 'undefined' && _browseState.path) ? _browseState.path : '';
}

function _clearFolderDropHighlight() {
  var el = document.getElementById('folderBrowser');
  if (el) el.classList.remove('fb-drop-active');
  document.querySelectorAll('.folder-item.fb-drop-row')
    .forEach(function (r) { r.classList.remove('fb-drop-row'); });
}

/** Attached workspace roots (single source of truth: projectState). A drop is
 *  only accepted inside one of these — the backend save_uploaded_file refuses
 *  anything else, so we mirror that guard client-side for a clear, proactive
 *  message instead of a generic post-hoc "failed to save". */
function _attachedRootPaths() {
  var roots = [];
  if (typeof projectState !== 'undefined' && projectState) {
    if (projectState.path) roots.push(projectState.path);
    (projectState.extraRoots || []).forEach(function (r) {
      var p = typeof r === 'string' ? r : (r && r.path);
      if (p) roots.push(p);
    });
  }
  return roots;
}

/** True if `dir` is (or is under) an attached root. Empty dir → the active
 *  project root, which the backend resolves, so it's allowed. */
function _dirInsideAttachedRoot(dir) {
  if (!dir) return true;
  var norm = function (p) { return String(p).replace(/\/+$/, ''); };
  var d = norm(dir);
  return _attachedRootPaths().some(function (root) {
    var r = norm(root);
    return d === r || d.indexOf(r + '/') === 0;
  });
}

/** Save one dropped File into `dir` via the binary-safe upload endpoint. */
async function _uploadDroppedFile(file, dir) {
  var fd = new FormData();
  fd.append('file', file, file.name);
  if (dir) fd.append('dir', dir);
  var resp = await Api.project.upload(fd);
  var data = resp ? await resp.json().catch(function () { return {}; }) : {};
  if (resp && resp.ok && data && data.ok) return { ok: true, data: data };
  return { ok: false, error: (data && data.error) || ('HTTP ' + (resp ? resp.status : '?')) };
}

function _attachFolderDropZone() {
  if (_folderDropAttached) return;
  var el = document.getElementById('folderBrowser');
  if (!el) return;
  _folderDropAttached = true;

  var hasFiles = function (e) {
    return e.dataTransfer && Array.prototype.indexOf.call(e.dataTransfer.types || [], 'Files') !== -1;
  };

  el.addEventListener('dragover', function (e) {
    if (!hasFiles(e)) return;
    e.preventDefault();
    e.stopPropagation();
    if (e.dataTransfer) e.dataTransfer.dropEffect = 'copy';
    el.classList.add('fb-drop-active');
    var row = e.target.closest ? e.target.closest('.folder-item[data-dir-path]') : null;
    document.querySelectorAll('.folder-item.fb-drop-row')
      .forEach(function (r) { if (r !== row) r.classList.remove('fb-drop-row'); });
    if (row) row.classList.add('fb-drop-row');
  }, true);

  el.addEventListener('dragleave', function (e) {
    // Only clear when the pointer actually leaves the browser box.
    if (e.target === el && !el.contains(/** @type {Node} */(e.relatedTarget))) _clearFolderDropHighlight();
  }, true);

  el.addEventListener('drop', function (e) {
    if (!hasFiles(e)) return;
    e.preventDefault();
    e.stopPropagation();  // beat the document-level chat-drop handler
    var dir = _folderDropTargetDir(e.target);
    _clearFolderDropHighlight();
    var files = Array.prototype.slice.call((e.dataTransfer && e.dataTransfer.files) || []);
    if (!files.length) return;
    _runFolderDrop(files, dir);
  }, true);
}

/** Add `dir` to the workspace as an extra root (or primary if none yet),
 *  reusing the tested setPaths apply path. Preserves existing roots + their
 *  read-only flags. Throws on server failure. */
async function _addDropDirAsRoot(dir) {
  var folders = _attachedRootPaths().slice();
  if (folders.indexOf(dir) === -1) folders.push(dir);
  var readOnly = [];
  if (typeof projectState !== 'undefined' && projectState) {
    if (projectState.readOnly && projectState.path) readOnly.push(projectState.path);
    (projectState.extraRoots || []).forEach(function (r) {
      if (r && typeof r === 'object' && r.readOnly && r.path) readOnly.push(r.path);
    });
  }
  var resp = await Api.project.setPaths(folders, readOnly);
  var data = resp ? await resp.json().catch(function () { return {}; }) : {};
  if (!resp || !resp.ok) throw new Error((data && data.error) || 'Failed to add folder');
  if (typeof _applyProjectData === 'function') _applyProjectData(data);
  if (typeof _saveConvProjectPath === 'function') {
    _saveConvProjectPath(data.path,
      (data.extraRoots || []).map(function (r) { return typeof r === 'string' ? r : r.path; }),
      readOnly);
  }
}

async function _runFolderDrop(files, dir) {
  var dirLabel = dir ? (dir.split('/').filter(Boolean).slice(-1)[0] || dir) : 'project root';
  // A drop outside every attached root would be refused by save_uploaded_file
  // (it never auto-registers a workspace). Rather than dead-ending, OFFER to
  // add the folder in one click — the upload itself is harmless, but adding a
  // root has a visible side effect (a scan + a new project-bar folder), so we
  // ask first instead of doing it silently.
  if (dir && !_dirInsideAttachedRoot(dir)) {
    var ok = (typeof showConfirm === 'function')
      ? await showConfirm(t('folderDrop.addRootConfirm', { dir: dirLabel }),
          { title: t('folderDrop.notInWorkspace'),
            okText: t('folderDrop.addAndSave') })
      : true;
    if (!ok) return;
    try {
      await _addDropDirAsRoot(dir);
    } catch (e) {
      if (typeof showToast === 'function') {
        showToast(t('folderDrop.failed', { n: files.length }), 'error',
          (e && e.message) || '', 6000);
      }
      return;
    }
  }
  var results = await Promise.allSettled(files.map(function (f) {
    return _uploadDroppedFile(f, dir);
  }));
  var saved = 0, renamed = 0;
  var errors = [];
  results.forEach(function (r, i) {
    if (r.status === 'fulfilled' && r.value && r.value.ok) {
      saved++;
      if (r.value.data && r.value.data.renamed) renamed++;
    } else {
      var msg = (r.status === 'fulfilled' && r.value)
        ? r.value.error
        : (r.status === 'rejected' && r.reason && r.reason.message);
      errors.push(files[i].name + ': ' + (msg || 'failed'));
    }
  });
  if (typeof showToast === 'function') {
    if (saved > 0) {
      var detail = t('folderDrop.savedInto', { dir: dirLabel })
        + (renamed ? ' · ' + t('folderDrop.renamedNote', { n: renamed }) : '');
      showToast(t('folderDrop.saved', { n: saved }), '', detail, 4200);
    }
    if (errors.length) {
      showToast(t('folderDrop.failed', { n: errors.length }), 'error',
        errors.slice(0, 3).join('\n'), 6000);
    }
  }
  // Refresh so the newly-saved files reflect in the browser's file count.
  if (typeof browseDirectory === 'function' && typeof _browseState !== 'undefined' && _browseState.path) {
    browseDirectory(_browseState.path);
  }
  // Surface the write in the project bar's file-changes affordance.
  if (typeof loadProjectStatus === 'function') { try { loadProjectStatus(); } catch (_e) { /* best-effort */ } }
}

/* ===== migrated source: ui/finish_info_rich.js ===== */
/* ui/finish_info_rich.js — DEFERRED cost-popover family (Epic-E
 * pt_3879f00e sub-8, split out of ui/finish_info.js 2026-08-01).
 *
 * _buildCostPopover (19KB per-round cost/cache-break breakdown) + the
 * popover interaction cluster (_toggleCostPopover / _hideCostPopover /
 * outside-click / scroll-dismiss). The finish bar used to embed the
 * fully-built popover HTML into every painted message; now
 * renderFinishInfo (core) stashes the build ctx in _costCtxByMsg and
 * the popover builds on FIRST open after the feature bridge prepares this
 * lazy ESM domain → _toggleCostPopover builds + shows. The cache-break
 * phrase family (_CACHE_CAUSE_PHRASES / _translateCacheCause /
 * _cacheBreakReason / _cacheBreakState / _cacheBreakCulprits / _CP_*_SVG)
 * STAYS in core (the collapsed bar's warn tooltip renders at paint).
 */

function _buildCostPopover(ctx) {
  const { costInfo, rounds, numRounds, u, inp, out, cw, cr, thk, mid, pid, taskId, toolRounds } = ctx;
  const fmt = (n) => (n >= 1000000 ? (n / 1000000).toFixed(1) + "m" : n >= 1000 ? (n / 1000).toFixed(1) + "k" : (n || 0).toString());
  const fCny = (v) => (v >= 0.01 ? "¥" + v.toFixed(3) : v > 0 ? "¥" + v.toFixed(4) : "¥0");
  const _dbg = (typeof _featureFlags !== 'undefined' && _featureFlags.debug_mode);

  let html = '';

  // ── Per-round breakdown table ──
  if (numRounds > 1) {
    html += `<div class="cp-section-title">${escapeHtml(t('finishInfo.apiRoundsTitle', { n: numRounds }))}</div>`;
    html += `<div class="cp-rounds">`;
    // ★ Per-round tool names. The backend stamps `rd.toolCalls` (authoritative,
    //   exactly the tool_calls the model emitted), but it's absent on every
    //   message persisted before that stamp shipped. Derive a fallback from
    //   the message's toolRounds[] — each carries toolName + llmRound (0-based),
    //   and a displayed round with numeric `round` (1-based) maps as
    //   round === llmRound + 1. This makes the activity line work for EVERY
    //   message (old + new) with zero backend round-trip.
    const _toolsByLlmRound = {};
    // Per-llmRound tool RESULT token metadata — drives the "工具结果流入" line.
    // Each entry: {name, tokens}. tokens come from toolRounds[].toolTokens
    // (the same local count the ptool panel badge shows), 0 when absent.
    const _toolMetaByLlmRound = {};
    for (const tr of (Array.isArray(toolRounds) ? toolRounds : [])) {
      if (!tr || typeof tr !== 'object') continue;
      const _lr = tr.llmRound;
      const _nm = tr.toolName || tr.name;
      if (typeof _lr !== 'number' || !_nm) continue;
      (_toolsByLlmRound[_lr] = _toolsByLlmRound[_lr] || []).push(_nm);
      (_toolMetaByLlmRound[_lr] = _toolMetaByLlmRound[_lr] || [])
        .push({ name: _nm, tokens: (typeof tr.toolTokens === 'number' ? tr.toolTokens : 0) });
    }
    const _roundToolNames = rounds.map((rd) => {
      if (Array.isArray(rd.toolCalls) && rd.toolCalls.length) return rd.toolCalls;
      const _rnum = rd.round;
      if (typeof _rnum === 'number' && _toolsByLlmRound[_rnum - 1]) {
        return _toolsByLlmRound[_rnum - 1];
      }
      return [];
    });
    // Parallel to _roundToolNames, but with per-tool RESULT token sizes (the
    // same numbers the ptool panel badges show). A round whose apiRound `round`
    // is R maps to llmRound R-1, so display-round index i (round R=i+1) carries
    // the tools tagged llmRound i. Used to render the concrete inflow line —
    // these results flow into the NEXT round's context/write.
    const _roundToolMeta = rounds.map((rd) => {
      const _rnum = rd.round;
      if (typeof _rnum === 'number' && _toolMetaByLlmRound[_rnum - 1]) {
        return _toolMetaByLlmRound[_rnum - 1];
      }
      return [];
    });
    // Format a tool-meta list as "name S、name S（计 T）" with token sizes.
    const _fmtToolMeta = (meta) => {
      let _sum = 0;
      const _parts = meta.map((m) => {
        _sum += (m.tokens || 0);
        return m.tokens ? `${m.name} ${fmt(m.tokens)}` : m.name;
      });
      const _body = _parts.join(t('finishInfo.listSepDot'));
      return _sum > 0 ? `${_body}${t('finishInfo.metaSum', { v: fmt(_sum) })}` : _body;
    };
    rounds.forEach((rd, i) => {
      const ru = rd.usage || {};
      const ri = ru.prompt_tokens || ru.input_tokens || 0;
      const ro = ru.completion_tokens || ru.output_tokens || 0;
      const rt = ru.reasoning_tokens || ru.thinking_tokens || 0;
      const rcw = ru.cache_write_tokens || ru.cache_creation_input_tokens || 0;
      const rcr = ru.cache_read_tokens || ru.cache_read_input_tokens || 0;
      const rdCost = rd.cost || calcCostCny(ru, mid, rd.provider_id || rd.providerId || pid);
      // Honest cost label. calcCostCny returns null for BOTH "genuinely no
      // charge" AND "couldn't obtain the server number" (fetch pending or
      // failed). Only print ¥0 in the FIRST case — when the round consumed no
      // billable tokens at all. If the round DID consume tokens but we have no
      // server cost yet, show "…" (待计算), never a fabricated ¥0 for a round
      // that cost money. The only source of truth is the backend.
      let rdCnyStr;
      if (rdCost) {
        rdCnyStr = fCny(rdCost.costCny);
      } else {
        const _billable = (ri + ro + rt + rcw + rcr) > 0;
        rdCnyStr = _billable ? "…" : "¥0";
      }
      let rdLabel = t("toolPanel.roundTag", { n: i + 1 });
      if (rd.tag && rd.tag.includes("FALLBACK")) rdLabel += t('finishInfo.fallbackSuffix');
      // API key that served this round (from dispatch metadata).
      const _disp = ru._dispatch || {};
      const _keyTail = _disp.key_tail;
      const _keyStr = _keyTail ? ('••' + _keyTail) : (_disp.key || '');
      const _model = _disp.model || rd.model || '';
      // Cache-break reason stamped by the backend onto this round.
      const cbReason = _cacheBreakReason(rd.cacheBreak);
      // Fault STATE (proven-server / unproven / our-culprit) + the named
      // culprit list, so the popover shows WHOSE fault and WHICH message.
      const cbState = _cacheBreakState(rd.cacheBreak);
      const cbCulprits = _cacheBreakCulprits(rd.cacheBreak);

      html += `<div class="cp-round">`;
      html += `<div class="cp-round-head">`;
      html += `<span class="cp-round-label">${escapeHtml(rdLabel)}</span>`;
      html += `<span class="cp-round-cost">${escapeHtml(rdCnyStr)}</span>`;
      html += `</div>`;
      html += `<div class="cp-round-tokens">`;
      html += `<span>${escapeHtml(fmt(ri))} → ${escapeHtml(fmt(ro))}</span>`;
      if (rt > 0) html += `<span class="cp-think">✶${escapeHtml(fmt(rt))}</span>`;
      if (rcr > 0) html += `<span class="cp-hit">cache ${escapeHtml(fmt(rcr))}</span>`;
      if (rcw > 0) html += `<span class="cp-write">write ${escapeHtml(fmt(rcw))}</span>`;
      html += `</div>`;
      // ★ Inflow line: the tool RESULTS that flowed INTO this round's
      //   context (= the PREVIOUS round's tool calls, fed back). This is ONE
      //   component of this round's `write` — NOT the whole thing. The write
      //   also covers the previous round's assistant turn (reasoning text +
      //   the serialized tool_call argument blocks) plus per-message JSON/role
      //   envelope overhead. We reconcile EXPLICITLY against `rcw` so the two
      //   numbers visibly add up instead of looking contradictory: the seam is
      //   end-to-end traceable: ptool badge → 工具结果 → +其余 = this round's write.
      const _inflowMeta = i > 0 ? (_roundToolMeta[i - 1] || []) : [];
      // The authoritative `write` decomposition computed on the BACKEND
      // (lib/tasks_pkg/orchestrator._compute_write_breakdown) from real
      // recorded usage, stamped on rd.writeBreakdown as
      // {write, toolResults, prevOutput, recacheBody, envelope}. Its sub-items
      // sum to EXACTLY `write` by construction, so we render it as a single
      // plain equation a reader can verify adds up. The per-tool sizes (the
      // ptool-badge numbers) are measured with a DIFFERENT tokenizer and do
      // NOT match these provider-side components, so they live in the tooltip
      // only — never on the same line next to a `=` (that was the
      // "833 = 214 / 工具结果=833 vs 工具结果=42" contradiction users hit).
      const _wb = rd.writeBreakdown;
      let _wbShown = false;
      if (_wb && _wb.write > 0) {
        const _terms = [];
        if (_wb.prevOutput > 0)   _terms.push(t('finishInfo.wbPrevOutput', { v: fmt(_wb.prevOutput) }));
        if (_wb.toolResults > 0) {
          // Make the offset-by-one explicit ON THE ROW (not buried in the
          // tooltip): the tool RESULTS in round (i+1)'s write came from the
          // PREVIOUS round's tool batch, which the tool panel labels 第i轮.
          // Round display index i maps to llmRound i; its inflow is llmRound
          // i-1 = tool batch label i. Annotating the batch number lets a
          // reader cross-check the two panels directly instead of inferring
          // the offset (the "第3轮 vs 批次3 never matches" confusion).
          let _tr = t('finishInfo.wbToolResults', { v: fmt(_wb.toolResults) });
          if (i > 0) _tr += t('finishInfo.wbBatchRef', { n: i });
          _terms.push(_tr);
        }
        if (_wb.contextWrite > 0) _terms.push(t('finishInfo.wbContextWrite', { v: fmt(_wb.contextWrite) }));
        if (_wb.recacheBody > 0)  _terms.push(t('finishInfo.wbRecacheBody', { v: fmt(_wb.recacheBody) }));
        if (_wb.envelope > 0)     _terms.push(t('finishInfo.wbEnvelope', { v: fmt(_wb.envelope) }));
        if (_terms.length) {
          let _tip = t('finishInfo.wbTipHead', { v: fmt(_wb.write) });
          if (_wb.prevOutput > 0)  _tip += t('finishInfo.wbTipPrevOutput', { v: fmt(_wb.prevOutput) });
          if (_wb.toolResults > 0) {
            _tip += t('finishInfo.wbTipToolResults', { v: fmt(_wb.toolResults) });
            if (_inflowMeta.length) _tip += t('finishInfo.wbTipToolResultsDetail', { detail: _fmtToolMeta(_inflowMeta) });
          }
          if (_wb.contextWrite > 0) _tip += t('finishInfo.wbTipContextWrite', { v: fmt(_wb.contextWrite) });
          if (_wb.recacheBody > 0) {
            _tip += t('finishInfo.wbTipRecacheBody', { v: fmt(_wb.recacheBody) });
            if (_wb.readDrop > 0) _tip += t('finishInfo.wbTipReadDrop', { v: fmt(_wb.readDrop) });
            if (cbReason) _tip += t('finishInfo.wbTipSeeBreak');
          }
          if (_wb.envelope > 0)    _tip += t('finishInfo.wbTipEnvelope', { v: fmt(_wb.envelope) });
          if (_wb.capped) _tip += t('finishInfo.wbTipCapped');
          // When the components were capped (local-vs-provider tokenizer
          // mismatch) they do NOT add up exactly — use ≈ and an explicit
          // "约" so the row isn't presented as an exact equation.
          const _sumLabel = _wb.capped
            ? t('finishInfo.wbSumApprox', { v: fmt(_wb.write), terms: escapeHtml(_terms.join(' + ')) })
            : t('finishInfo.wbSum', { v: fmt(_wb.write), terms: escapeHtml(_terms.join(' + ')) });
          html += `<div class="cp-round-act cp-round-inflow" title="${escapeHtml(_tip)}">${_sumLabel}</div>`;
          _wbShown = true;
        }
        // ★ Re-cache WASTE line. When the backend attributed part of this
        //   round's write to `recacheBody` (already-cached body re-billed) but
        //   the banner-level detector stayed SILENT (no rd.cacheBreak — the
        //   sub-threshold / cross-turn round-1 read drop the Stage-1 fix now
        //   catches), the "重新缓存正文" term would otherwise sit bare in the
        //   equation with no explanation. Surface it from the breakdown's own
        //   data (recacheBody + readDrop) so the user SEES why the round cost
        //   money. Suppressed when a banner cbReason IS present — the
        //   cp-round-break line below explains it and two lines would duplicate.
        if (_wb.recacheBody > 0 && !cbReason) {
          const _wasteTip = t('finishInfo.wbWasteTip', {
            v: fmt(_wb.recacheBody), drop: fmt(_wb.readDrop || 0) });
          html += `<div class="cp-round-waste" title="${escapeHtml(_wasteTip)}">${escapeHtml(t('finishInfo.wbWasteLabel', { v: fmt(_wb.recacheBody), drop: fmt(_wb.readDrop || 0) }))}</div>`;
        }
      }
      if (!_wbShown && _inflowMeta.length) {
        // Legacy fallback (rounds persisted before writeBreakdown shipped):
        // just name the previous round's tool results that flowed in. No `=`,
        // no fake equation — these local counts don't equal write.
        const _inflowStr = _fmtToolMeta(_inflowMeta);
        const _tip = t('finishInfo.inflowTip', { n: _inflowMeta.length });
        html += `<div class="cp-round-act cp-round-inflow" title="${escapeHtml(_tip)}">${escapeHtml(t('finishInfo.inflowLabel', { detail: _inflowStr }))}</div>`;
      }
      // ★ Activity line: what the model DID this round (the tool calls it
      //   emitted). This is the causal driver of the NEXT round's `write`.
      const _tcNames = _roundToolNames[i] || [];
      if (_tcNames.length) {
        const _counts = {};
        for (const n of _tcNames) _counts[n] = (_counts[n] || 0) + 1;
        const _actStr = Object.keys(_counts)
          .map(n => _counts[n] > 1 ? `${n}×${_counts[n]}` : n).join(t('finishInfo.listSepDot'));
        html += `<div class="cp-round-act" title="${escapeHtml(t('finishInfo.actTip', { n: _tcNames.length }))}">${escapeHtml(t('finishInfo.actLabel', { n: _tcNames.length, tools: _actStr }))}</div>`;
      } else if (i === rounds.length - 1) {
        // Last round with no tool calls = the model's final text answer.
        // Tag it so a user doesn't wonder why the round count (API rounds)
        // exceeds the tool-batch count in the ptool panel.
        html += `<div class="cp-round-act cp-round-final" title="${escapeHtml(t('finishInfo.finalTip'))}">${escapeHtml(t('finishInfo.finalLabel'))}</div>`;
      }
      // ★ Explain a write that's much larger than this round's own output:
      //   the `write` is NOT what the model generated — it's the PREVIOUS
      //   round's output + the tool RESULTS that came back, newly cached.
      //   Only annotate when the gap is real (write ≫ output) to avoid noise.
      const _prev = i > 0 ? rounds[i - 1] : null;
      const _prevTcs = i > 0 ? (_roundToolNames[i - 1] || []).length : 0;
      // Suppress the "healthy warming write" note when this round is flagged
      // as a real cache miss (cbReason) OR the authoritative writeBreakdown
      // equation was already shown (_wbShown). The legacy heuristic note used
      // to fire redundantly ON TOP of the exact breakdown — worse, on a turn's
      // round-1 it claimed "上一轮产出 + 工具结果" for a round that has no
      // previous output, directly contradicting the equation above it. The
      // breakdown row is authoritative; only fall back to the heuristic note
      // when NO breakdown was rendered (legacy rounds persisted before it).
      if (!cbReason && !_wbShown && !_inflowMeta.length && rcw > 2000 && rcw > ro * 2 && (_prev || _prevTcs)) {
        const _why = _prevTcs
          ? t('finishInfo.writeNoteTipTools', { v: fmt(rcw), n: _prevTcs })
          : t('finishInfo.writeNoteTipPlain', { v: fmt(rcw) });
        html += `<div class="cp-round-note" title="${escapeHtml(_why)}">${escapeHtml(t('finishInfo.writeNoteLabel'))}</div>`;
      }
      // Meta line: key + (debug) trace.
      const metaBits = [];
      if (_keyStr) metaBits.push(`<span class="cp-key" title="${escapeHtml('Key: ' + _keyStr + (_model ? '  ·  Model: ' + _model : ''))}">${_CP_KEY_SVG}${escapeHtml(_keyStr)}</span>`);
      if (_dbg && ru.trace_id) metaBits.push(`<span class="cp-trace">${escapeHtml(ru.trace_id.slice(0, 8))}</span>`);
      if (metaBits.length) html += `<div class="cp-round-meta">${metaBits.join('')}</div>`;
      if (cbReason) {
        // State-tagged line: green-ish 'proven server' (not our fault),
        // amber 'unproven' (unknown), red 'culprit' (our fault, actionable).
        const _stCls = cbState ? ` cp-break-${cbState}` : '';
        const _stLabel = cbState ? `<span class="cp-break-badge cp-break-badge-${cbState}">${t('finishInfo.cbState.' + cbState)}</span>` : '';
        // The reason prose MUST be wrapped in its own span: as a bare text
        // node it becomes an anonymous flex item whose CJK min-content is ONE
        // character, so a long state badge (e.g. 'upstream') squeezes it to a
        // 1-char-per-line column (2026-07-24 overflow bug).
        html += `<div class="cp-round-break${_stCls}">${_CP_WARN_SVG}${_stLabel}<span class="cp-break-text">${t('finishInfo.cacheBreakLabel', { reason: cbReason })}</span></div>`; 
        // The named culprit — WHICH message(s) broke cache — surfaced on its
        // own line so the user can act on it, not hunt error.log.
        if (cbCulprits) {
          html += `<div class="cp-break-culprit">${t('finishInfo.cbCulpritLabel', { culprits: escapeHtml(cbCulprits) })}</div>`;
        }
      }
      html += `</div>`;
    });
    html += `</div>`;
    // ★ Legend — explains the cache/write/→ semantics so a user isn't
    //   puzzled why "531 output" becomes "1.5k write" next round.
    html += `<div class="cp-legend">`
      + `<span class="cp-legend-item">${t('finishInfo.legendXY')}</span>`
      + `<span class="cp-legend-item">${t('finishInfo.legendCache')}</span>`
      + `<span class="cp-legend-item">${t('finishInfo.legendWrite')}</span>`
      + `</div>`;
  }

  // ── Aggregate cost rows ──
  html += `<div class="cp-totals">`;
  const _si = costInfo.inputTokens || 0;
  const _totalInp = costInfo.totalInputTokens || inp;
  const _inTokens = (_totalInp > _si && _si >= 0) ? _si : inp;
  const row = (label, val, cls) =>
    `<div class="cp-row${cls ? ' ' + cls : ''}"><span class="cp-row-label">${label}</span><span class="cp-row-val">${escapeHtml(val)}</span></div>`;
  html += row('Input', `${fmt(_inTokens)} → ${fCny(costInfo.inputCostCny)}`);
  if (cw > 0) html += row('Cache write', `${fmt(cw)} → ${fCny(costInfo.cacheWriteCostCny)}`);
  if (cr > 0) html += row('Cache read', `${fmt(cr)} → ${fCny(costInfo.cacheReadCostCny)}`);
  html += row('Output', `${fmt(out)} → ${fCny(costInfo.outputCostCny)}`);
  if (thk > 0) html += row('Thinking', `${fmt(thk)} ${t('finishInfo.thinkingInOutput')}`, 'cp-row-sub');
  if (costInfo.cacheSavingsCny > 0) html += row(t('finishInfo.cacheSavings'), fCny(costInfo.cacheSavingsCny), 'cp-row-save');
  html += `</div>`;

  // ── Total ──
  html += `<div class="cp-total-row"><span>Total</span><span class="cp-total-val">${escapeHtml(formatCny(costInfo.costCny))}</span></div>`;

  // ── Task ID (the whole user→assistant turn, across ALL tool rounds) ──
  //   Always shown (not debug-gated): this is the single id the user quotes
  //   back to us so we can grep the matching '[Task:<id>]' lines in app.log
  //   for root-cause analysis. Click to copy.
  if (taskId) {
    const _tidSafe = String(taskId).replace(/\\/g, '\\\\').replace(/'/g, "\\'");
    html += `<div class="cp-taskid-row" title="${escapeHtml(t('finishInfo.taskIdTip', { id: taskId }))}" data-tofu-action="event.stopPropagation();_safeClipboardWrite('${_tidSafe}');this.classList.add('cp-copied')">Task ID: <span class="cp-taskid-val">${escapeHtml(taskId)}</span></div>`;
  }

  // ── Trace ids (debug only) ──
  if (_dbg) {
    const traceIds = rounds.map(rd => (rd.usage || {}).trace_id).filter(Boolean);
    const lastTrace = traceIds.length ? traceIds[traceIds.length - 1] : (u.trace_id || '');
    if (lastTrace) {
      html += `<div class="cp-trace-row" title="${escapeHtml(traceIds.join('\n') || lastTrace)}">TraceId: ${escapeHtml(lastTrace)}</div>`;
    }
  }

  return html;
}

// One floating popover element, reused across cost tags.
let _costPopoverEl = null;

function _hideCostPopover() {
  if (_costPopoverEl) { _costPopoverEl.remove(); _costPopoverEl = null; }
  document.removeEventListener('click', _costPopoverOutside, true);
  window.removeEventListener('scroll', _costPopoverScroll, true);
  window.removeEventListener('resize', _hideCostPopover, true);
}

function _costPopoverOutside(e) {
  if (_costPopoverEl && !_costPopoverEl.contains(e.target) && !e.target.closest('.cost-tag-detail')) {
    _hideCostPopover();
  }
}

// Scroll-dismiss handler. Registered with capture:true so it fires for
// ANY scroll on the page — but a scroll INSIDE the popover (its own
// .cp-rounds / body overflow) must NOT close it, else the panel can never
// be scrolled. Ignore scrolls whose target is within the popover.
function _costPopoverScroll(e) {
  if (_costPopoverEl && _costPopoverEl.contains(e.target)) return;
  _hideCostPopover();
}

/** Toggle the floating cost popover anchored to the clicked cost tag. */
function _toggleCostPopover(ev, tagEl) {
  ev.stopPropagation();
  const wasOpen = _costPopoverEl && _costPopoverEl._anchor === tagEl;
  _hideCostPopover();
  if (wasOpen) return;

  const data = tagEl.querySelector('.cost-popover-data');
  if (!data) return;
  /* Lazy build (Epic-E sub-8): the core bar no longer embeds pre-built
   * popover HTML — renderFinishInfo stashes the build ctx in the
   * _costCtxByMsg WeakMap and this module (deferred) builds on FIRST
   * open. Embedded content (a mixed-shape bundle where core still
   * embeds) wins when present. */
  if (!data.innerHTML.trim()) {
    const _idx = (typeof _msgElIndex === 'function') ? _msgElIndex(tagEl) : -1;
    const _conv = (typeof getActiveConv === 'function') ? getActiveConv() : null;
    const _msg = (_conv && _conv.messages && _idx >= 0) ? _conv.messages[_idx] : null;
    const _ctx = _msg && (typeof _costCtxByMsg !== 'undefined') && _costCtxByMsg.get(_msg);
    if (_ctx) data.innerHTML = _buildCostPopover(_ctx);
  }
  if (!data.innerHTML.trim()) return;

  const pop = document.createElement('div');
  pop.className = 'cost-popover';
  pop._anchor = tagEl;
  pop.innerHTML = data.innerHTML;
  pop.style.position = 'fixed';
  pop.style.top = '-9999px';
  pop.style.left = '-9999px';
  document.body.appendChild(pop);

  const M = 8;                       // viewport margin
  const GAP = 8;                     // gap between tag and popover
  const vh = window.innerHeight;
  const r = tagEl.getBoundingClientRect();
  const pw = pop.offsetWidth || 320;
  let ph = pop.offsetHeight || 200;

  // Horizontal: align left edge to the tag, clamp into the viewport.
  let left = Math.round(r.left);
  const maxLeft = window.innerWidth - pw - M;
  if (left > maxLeft) left = Math.max(M, maxLeft);
  if (left < M) left = M;

  // Vertical: pick the side (above / below) with more room, then cap the
  // popover's max-height to the available space so a tall breakdown gets an
  // internal scrollbar instead of overflowing off-screen.
  const spaceAbove = r.top - GAP - M;
  const spaceBelow = vh - r.bottom - GAP - M;
  let top;
  if (ph <= spaceAbove) {
    top = Math.round(r.top - ph - GAP);          // fits above
  } else if (ph <= spaceBelow) {
    top = Math.round(r.bottom + GAP);            // fits below
  } else if (spaceAbove >= spaceBelow) {
    pop.style.maxHeight = `${Math.max(120, Math.floor(spaceAbove))}px`;
    ph = pop.offsetHeight;
    top = Math.round(Math.max(M, r.top - ph - GAP));
  } else {
    pop.style.maxHeight = `${Math.max(120, Math.floor(spaceBelow))}px`;
    top = Math.round(r.bottom + GAP);
  }
  pop.style.left = `${left}px`;
  pop.style.top = `${top}px`;
  _costPopoverEl = pop;

  setTimeout(() => {
    document.addEventListener('click', _costPopoverOutside, true);
    window.addEventListener('scroll', _costPopoverScroll, true);
    window.addEventListener('resize', _hideCostPopover, true);
  }, 0);
}

/* ===== migrated source: tools_panel.js ===== */
/* ═══════════════════════════════════════════════════════
   tools_panel.js — Settings → 工具 tab (live registry catalogue)

   Renders GET /api/v1/tools (lib/tools/registry/_introspect.py):
   every tool family registered in this process, grouped by category.
   This is a process-global catalogue: request-local gate/toggle state is
   deliberately not rendered. Pure-read panel — no mutations.

   This file is concatenated by Vite's module graph (the migrated lazy-module graph);
   symbols share the global window scope. No exports / imports.
   ═══════════════════════════════════════════════════════ */

var _toolsInvData = null;        // last inventory payload from /api/v1/tools
var _toolsInvQuery = '';
var _toolsInvRequestSeq = 0;     // a slow older refresh must not win the race

// ── Population (called from openSettings → _populateToolsTab) ──
async function _populateToolsTab() {
  var body = document.getElementById('toolsInvBody');
  var requestSeq = ++_toolsInvRequestSeq;
  if (body) body.setAttribute('aria-busy', 'true');
  try {
    var data = await Api.tools.inventory();
    if (!data) throw new Error(t('toolsInv.noResponse'));
    if (requestSeq !== _toolsInvRequestSeq) return;
    _toolsInvData = data;
    _toolsInvRender();
  } catch (e) {
    if (requestSeq !== _toolsInvRequestSeq) return;
    debugLog('[ToolsPanel] Failed to load inventory: ' + (e && e.message), 'error');
    if (body) body.innerHTML = '<p class="stg-empty">' +
      escapeHtml(t('toolsInv.loadFailed', { err: (e && e.message) || '?' })) + '</p>';
  } finally {
    if (body && requestSeq === _toolsInvRequestSeq) body.removeAttribute('aria-busy');
  }
}

function _toolsInvSearch(q) {
  _toolsInvQuery = (q || '').toLowerCase().trim();
  _toolsInvRender();
}

// ── Rendering (pure string builders — jsdom-testable) ────────

function _toolsInvLocalized(prefix, id, fallback) {
  var key = prefix + id;
  var value = t(key);
  // Future built-ins, plugins and MCP tools remain visible even before the
  // frontend gains a translation. Their server-authored description is the
  // honest fallback; never print a raw i18n key.
  return value === key ? (fallback || '') : value;
}

function _toolsInvFamilyDescription(fam) {
  return _toolsInvLocalized('toolsInv.family.', fam.key, fam.description);
}

function _toolsInvToolDescription(tool) {
  return _toolsInvLocalized('toolsInv.tool.', tool.name, tool.description);
}

function _toolsInvToolMatches(tool, q) {
  if (!q) return true;
  var hay = (tool.name + ' ' + (tool.description || '') + ' ' +
             _toolsInvToolDescription(tool)).toLowerCase();
  return hay.indexOf(q) !== -1;
}

function _toolsInvFamilyCounts(fam) {
  return { total: (fam.tools || []).length + (fam.mcp_tools || []).length };
}

function _toolsInvFamilyVisible(fam, q) {
  if (q) {
    var hay = (fam.key + ' ' + (fam.description || '') + ' ' +
               _toolsInvFamilyDescription(fam)).toLowerCase();
    if (hay.indexOf(q) !== -1) return true;
    // Family matches when ANY of its tools matches the query.
    return (fam.tools || []).some(function (tl) { return _toolsInvToolMatches(tl, q); }) ||
           (fam.mcp_tools || []).some(function (tl) { return _toolsInvToolMatches(tl, q); });
  }
  return true;
}

function _toolsInvRenderToolRow(tl, mcp) {
  var html = '<div class="tools-inv-tool">';
  html += '<div class="tools-inv-tool-head">';
  html += '<code class="tools-inv-tool-name">' + escapeHtml(tl.name) + '</code>';
  if (tl.write) {
    html += '<span class="tools-inv-badge is-write" title="' + escapeHtml(t('toolsInv.writeTitle')) + '">' + escapeHtml(t('toolsInv.writeBadge')) + '</span>';
  }
  if (mcp && tl.server) {
    html += '<span class="tools-inv-badge is-mcp">' + escapeHtml(tl.server) + '</span>';
  }
  html += '</div>';
  var description = _toolsInvToolDescription(tl);
  if (description) {
    html += '<div class="tools-inv-tool-desc">' + escapeHtml(description) + '</div>';
  }
  if (tl.required && tl.required.length) {
    html += '<div class="tools-inv-tool-req">' + escapeHtml(t('toolsInv.required')) + ' ' +
      tl.required.map(function (p) { return '<code>' + escapeHtml(p) + '</code>'; }).join(' ') + '</div>';
  }
  html += '</div>';
  return html;
}

function _toolsInvRenderFamily(fam, q) {
  var c = _toolsInvFamilyCounts(fam);
  var html = '<div class="tools-inv-family">';
  html += '<div class="tools-inv-family-head">';
  html += '<span class="tools-inv-family-name">' + escapeHtml(fam.key) + '</span>';
  if (fam.source === 'plugin') {
    html += '<span class="tools-inv-badge is-plugin">' + escapeHtml(t('toolsInv.pluginBadge')) +
            (fam.plugin_name ? ' · ' + escapeHtml(fam.plugin_name) : '') + '</span>';
  }
  html += '<span class="tools-inv-family-desc">' + escapeHtml(_toolsInvFamilyDescription(fam)) + '</span>';
  html += '<span class="tools-inv-family-count">' + escapeHtml(t('toolsInv.familyCount', { n: c.total })) + '</span>';
  html += '</div>';
  var rows = (fam.tools || []).filter(function (tl) { return _toolsInvToolMatches(tl, q); });
  var mcpRows = (fam.mcp_tools || []).filter(function (tl) { return _toolsInvToolMatches(tl, q); });
  if (rows.length || mcpRows.length) {
    html += '<div class="tools-inv-tools">';
    rows.forEach(function (tl) { html += _toolsInvRenderToolRow(tl, false); });
    mcpRows.forEach(function (tl) { html += _toolsInvRenderToolRow(tl, true); });
    html += '</div>';
  } else if (!c.total) {
    html += '<div class="tools-inv-empty">' + escapeHtml(t('toolsInv.familyEmpty')) + '</div>';
  }
  html += '</div>';
  return html;
}

// Group display order + i18n titles. Display PREFERENCE only (mirrors
// skills.js::_skillsOrderedCategories): a category absent here still renders,
// appended alphabetically — a new spec category must never be silently hidden.
var _TOOLS_INV_GROUP_ORDER = ['search', 'project', 'browser', 'desktop', 'image',
                              'video', 'conversation', 'human', 'memory', 'skills',
                              'knowledge', 'task', 'scheduler', 'swarm', 'mcp', 'custom'];

function _toolsInvGroupTitle(gid) {
  var key = 'toolsInv.group.' + gid;
  var v = t(key);
  // t() returns the key itself when missing — fall back to the raw id.
  return (v === key) ? gid : v;
}

function _toolsInvOrderedGroups(groups) {
  var byId = {};
  groups.forEach(function (g) { byId[g.id] = g; });
  var known = _TOOLS_INV_GROUP_ORDER.filter(function (id) { return byId[id]; });
  var extra = Object.keys(byId).filter(function (id) {
    return _TOOLS_INV_GROUP_ORDER.indexOf(id) === -1;
  }).sort();
  return known.concat(extra).map(function (id) { return byId[id]; });
}

function _toolsInvRender() {
  var body = document.getElementById('toolsInvBody');
  if (!body || !_toolsInvData) return;
  var inv = _toolsInvData;

  var totalEl = document.getElementById('toolsInvTotalCount');
  if (totalEl) totalEl.textContent = t('toolsInv.countTotal', { n: inv.totals.tools });

  var q = _toolsInvQuery;
  var html = '';
  var anyFamily = false;
  _toolsInvOrderedGroups(inv.groups || []).forEach(function (g) {
    var fams = (g.families || []).filter(function (f) {
      return _toolsInvFamilyVisible(f, q);
    });
    if (!fams.length) return;
    anyFamily = true;
    html += '<div class="tools-inv-group">';
    html += '<div class="tools-inv-group-title">' + escapeHtml(_toolsInvGroupTitle(g.id)) + '</div>';
    fams.forEach(function (f) { html += _toolsInvRenderFamily(f, q); });
    html += '</div>';
  });
  if (!anyFamily) {
    html = '<p class="stg-empty">' + escapeHtml(t('toolsInv.noMatch')) + '</p>';
  }
  body.innerHTML = html;
}

/* ===== migrated source: optimizer.js ===== */
/* ═══════════════════════════════════════════
   optimizer.js — Daily Optimizer panel
   Shows today's optimizer proposals, applied changes, and reverts.
   Mirrors the scheduler badge / panel UX.
   ═══════════════════════════════════════════ */

let _optimizerPanelOpen = false;
let _optimizerPollTimer = null;
let _optimizerLastRefresh = 0;

function toggleOptimizerPanel(e) {
  const panel = document.getElementById("optimizerPanel");
  if (!panel) return;
  // The panel is a DOM descendant of the badge, so clicks anywhere inside
  // the panel bubble up here. Without this guard, clicking a row, button,
  // or the "older proposals" header would flip _optimizerPanelOpen back to
  // false and close the popup.
  if (e && panel.contains(/** @type {Node} */ (e.target))) return;
  if (e) e.stopPropagation();
  _optimizerPanelOpen = !_optimizerPanelOpen;
  panel.classList.toggle("visible", _optimizerPanelOpen);
  if (_optimizerPanelOpen) _refreshOptimizerPanel();
}

function _optFmtTime(iso) {
  if (!iso) return "—";
  try {
    const d = new Date(iso);
    if (isNaN(d.getTime())) return iso.slice(0, 16);
    const now = new Date();
    const sameDay = d.toDateString() === now.toDateString();
    return sameDay ? d.toLocaleTimeString() : d.toLocaleString();
  } catch (e) {
    return iso.slice(0, 16);
  }
}

function _optStatusIcon(status) {
  switch (status) {
    case "applied": return IconDot('green');
    case "pending_review": return IconDot('yellow');
    case "rejected": return IconDot('red');
    case "expired": return IconDot('grey');
    case "reverted": return Icon('refresh', 12);
    default: return IconDot('grey');
  }
}

function _optSeverityColor(sev) {
  if (sev === "high") return "#f87171";
  if (sev === "med") return "#fbbf24";
  return "#60a5fa";
}

// Map the backend's English status_reason strings (from
// lib/optimizer/applier.py and routes/optimizer.py) to translated text.
// Falls back to the raw string for unrecognised reasons.
function _optStatusReasonText(reason) {
  if (!reason) return "";
  if (reason === "not in auto-apply whitelist") return t('optimizer.reason.notInWhitelist');
  if (reason === "dry_run") return t('optimizer.reason.dryRun');
  if (reason.indexOf("unknown action_type:") === 0) {
    const type = reason.slice("unknown action_type:".length).trim();
    return t('optimizer.reason.unknownAction', { type: type });
  }
  if (reason.indexOf("manual approve blocked") === 0) {
    return t('optimizer.reason.manualApproveBlocked');
  }
  return reason;
}

function _optRenderAction(p) {
  const args = p.action_args || {};
  const type = p.action_type || "other";
  if (type === "block_search_domain" && args.domain) {
    const ttl = args.ttl_days ? ` · ${args.ttl_days}d TTL` : "";
    return `${t('optimizer.blockSearchDomain')} <b>${escapeHtml(args.domain)}</b>${ttl}`;
  }
  if (type === "other") {
    return `${Icon('lightbulb', 13)} ${escapeHtml(p.title || t('optimizer.untitled'))}`;
  }
  // Fall-through: show type + first arg
  const firstArg = Object.keys(args).slice(0, 2).map(k => `${k}=${JSON.stringify(args[k]).slice(0, 30)}`).join(", ");
  return `${Icon('cog', 13)} ${escapeHtml(type)}${firstArg ? " <span style='color:var(--text-secondary)'>" + escapeHtml(firstArg) + "</span>" : ""}`;
}

function _optimizerFeatureEnabled() {
  if (typeof _featureFlags === "undefined") return true; // optimistic pre-load
  return _featureFlags.optimizer_enabled !== false;
}

async function _refreshOptimizerPanel() {
  try {
    if (!_optimizerFeatureEnabled()) {
      const countEl = document.getElementById("optimizerCount");
      if (countEl) countEl.style.display = "none";
      const badgeEl = document.getElementById("optimizerBadge");
      if (badgeEl) badgeEl.style.display = "none";
      const content = document.getElementById("optimizerPanelContent");
      if (content) content.innerHTML = '<div class="optimizer-panel-empty">' + t('optimizer.disabled') + '</div>';
      return;
    }
    const data = await Api.optimizer.proposals(60);
    if (!data || !data.ok) return;
    _optimizerLastRefresh = Date.now();

    const proposals = data.proposals || [];

    // Filter to "today" (server-local TZ matches client TZ closely enough for a badge count)
    const todayStart = new Date();
    todayStart.setHours(0, 0, 0, 0);
    const todays = proposals.filter(p => {
      try { return new Date(p.created_at) >= todayStart; } catch (e) { return false; }
    });

    const appliedToday = todays.filter(p => p.status === "applied");
    const pendingToday = todays.filter(p => p.status === "pending_review");
    const revertedToday = todays.filter(p => p.status === "reverted" || p.status === "expired");

    // Badge count = today's applied + pending (anything that changed behaviour today)
    const countEl = document.getElementById("optimizerCount");
    // The badge's display is driven by the feature flag (set on initial
    // feature-flags fetch + the Settings toggle).  Don't override it here.
    if (countEl) {
      const n = appliedToday.length + pendingToday.length;
      if (n > 0) {
        countEl.textContent = n;
        countEl.style.display = "inline-flex";
      } else {
        countEl.style.display = "none";
      }
    }

    const content = document.getElementById("optimizerPanelContent");
    if (!content) return;

    if (proposals.length === 0) {
      content.innerHTML = '<div class="optimizer-panel-empty">' + t('optimizer.empty') + '</div>' +
        '<div style="margin-top:10px;text-align:center"><button class="opt-run-btn" data-tofu-action="_optimizerRunNow()">' + t('optimizer.runNow') + '</button></div>';
      return;
    }

    // Group by section
    const sections = [
      { key: "applied", label: t('optimizer.appliedToday'), items: appliedToday },
      { key: "pending", label: t('optimizer.pendingReview'), items: pendingToday },
      { key: "reverted", label: t('optimizer.revertedToday'), items: revertedToday },
    ];
    let html = "";

    // Header: last run time + manual-run button
    html += `<div class="opt-toolbar">
      <span class="opt-toolbar-info">${t('optimizer.lastRefresh')}${new Date(_optimizerLastRefresh).toLocaleTimeString()}</span>
      <button class="opt-run-btn" data-tofu-action="_optimizerRunNow()" title="${t('optimizer.runNowTitle')}">${t('optimizer.runNow')}</button>
    </div>`;

    for (const sec of sections) {
      if (!sec.items.length) continue;
      html += `<div class="opt-section-title">${sec.label} <span class="opt-count">${sec.items.length}</span></div>`;
      for (const p of sec.items) {
        html += _renderOptimizerRow(p);
      }
    }

    // History — everything else (older than today)
    const older = proposals.filter(p => !todays.includes(p));
    if (older.length > 0) {
      html += `<div class="opt-section-title opt-history-header" data-tofu-action="_optToggleHistory()">
        ${t('optimizer.olderProposals')} <span class="opt-count">${older.length}</span>
        <span id="optHistoryArrow" style="float:right">▸</span>
      </div>`;
      html += '<div id="optHistoryBody" style="display:none">';
      for (const p of older.slice(0, 40)) {
        html += _renderOptimizerRow(p);
      }
      html += '</div>';
    }

    content.innerHTML = html;
  } catch (e) {
    console.warn("[Optimizer] Panel refresh failed:", e);
  }
}

function _optToggleHistory() {
  const body = document.getElementById("optHistoryBody");
  const arrow = document.getElementById("optHistoryArrow");
  if (!body) return;
  const open = body.style.display !== "none";
  body.style.display = open ? "none" : "block";
  if (arrow) arrow.textContent = open ? "▸" : "▾";
}

function _renderOptimizerRow(p) {
  const sev = p.severity || "low";
  const conf = typeof p.confidence === "number" ? Math.round(p.confidence * 100) : 50;
  const rationale = (p.rationale || "").slice(0, 260);
  const reasonText = _optStatusReasonText((p.status_reason || "").slice(0, 200));
  const reason = reasonText ? `<div class="opt-row-reason">${escapeHtml(reasonText)}</div>` : "";

  let actions = "";
  if (p.status === "pending_review") {
    actions = `
      <button class="opt-btn opt-btn-approve" data-tofu-action="_optApprove('${p.id}')" title="${t('optimizer.approveTitle')}">${t('optimizer.approve')}</button>
      <button class="opt-btn opt-btn-reject" data-tofu-action="_optReject('${p.id}')" title="${t('optimizer.rejectTitle')}">${t('optimizer.reject')}</button>
    `;
  } else if (p.status === "applied") {
    actions = `<button class="opt-btn opt-btn-revert" data-tofu-action="_optRevert('${p.id}')" title="${t('optimizer.revertTitle')}">${t('optimizer.revert')}</button>`;
  }

  return `<div class="opt-row opt-status-${p.status || 'unknown'}">
    <div class="opt-row-head">
      <span class="opt-status-icon">${_optStatusIcon(p.status)}</span>
      <span class="opt-action-summary">${_optRenderAction(p)}</span>
      <span class="opt-row-conf" style="color:${_optSeverityColor(sev)}" title="severity=${sev}, confidence=${conf}%">${sev.toUpperCase()} · ${conf}%</span>
    </div>
    <div class="opt-row-meta">
      <span>${_optFmtTime(p.created_at)}</span>
      ${p.title ? `· <span class="opt-row-title">${escapeHtml(p.title.slice(0, 90))}</span>` : ""}
    </div>
    ${rationale ? `<div class="opt-row-rationale">${escapeHtml(rationale)}${(p.rationale || "").length > 260 ? "…" : ""}</div>` : ""}
    ${reason}
    ${actions ? `<div class="opt-row-actions">${actions}</div>` : ""}
  </div>`;
}

async function _optApprove(id) {
  try {
    const data = await Api.optimizer.approve(id);
    if (data && data.ok) {
      debugLog(`🧭 Optimizer: proposal ${id.slice(0, 12)} approved & applied`, "success");
    } else {
      debugLog(`🧭 Approve failed: ${(data && data.error) || "unknown"}`, "error");
    }
  } catch (e) {
    debugLog(`🧭 Approve error: ${e.message}`, "error");
  }
  _refreshOptimizerPanel();
}

async function _optReject(id) {
  const reason = await showPrompt(t('optimizer.rejectPrompt'), { defaultValue: "" });
  try {
    const data = await Api.optimizer.reject(id, reason || "");
    if (data && data.ok) debugLog(`🧭 Optimizer: proposal ${id.slice(0, 12)} rejected`, "info");
    else debugLog(`🧭 Reject failed: ${(data && data.error) || "unknown"}`, "error");
  } catch (e) {
    debugLog(`🧭 Reject error: ${e.message}`, "error");
  }
  _refreshOptimizerPanel();
}

async function _optRevert(id) {
  if (!await showConfirm(t('optimizer.revertConfirm'), { danger: true })) return;
  try {
    const data = await Api.optimizer.revert(id);
    if (data && data.ok) debugLog(`🧭 Optimizer: proposal ${id.slice(0, 12)} reverted`, "success");
    else debugLog(`🧭 Revert failed: ${(data && data.error) || "unknown"}`, "error");
  } catch (e) {
    debugLog(`🧭 Revert error: ${e.message}`, "error");
  }
  _refreshOptimizerPanel();
}

async function _optimizerRunNow() {
  const btn = event && event.target;
  if (btn) { btn.disabled = true; btn.textContent = t('optimizer.running'); }
  try {
    const data = await Api.optimizer.runNow({ dry_run: false, window_hours: 24 });
    if (data && data.ok) {
      const s = data.summary || {};
      debugLog(
        `🧭 Optimizer: produced=${(s.proposals || []).length} applied=${(s.applied || []).length} pending=${(s.pending_review || []).length} reverts=${(s.reverts || []).length}`,
        "success"
      );
    } else {
      debugLog(`🧭 Run failed: ${(data && data.error) || "unknown"}`, "error");
    }
  } catch (e) {
    debugLog(`🧭 Run error: ${e.message}`, "error");
  } finally {
    if (btn) { btn.disabled = false; btn.textContent = t('optimizer.runNow'); }
    _refreshOptimizerPanel();
  }
}

// Bind the badge click handler here (formerly inline onclick in index.html).
// Inline onclick raced the `defer` script and threw ReferenceError if the
// user clicked before optimizer.js executed — see logs/error.log spam.
(function _bindOptimizerBadge() {
  function bind() {
    const badge = document.getElementById("optimizerBadge");
    if (!badge) return;
    if (badge.dataset.optimizerBound === "1") return;
    badge.dataset.optimizerBound = "1";
    badge.addEventListener("click", toggleOptimizerPanel);
  }
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", bind);
  } else {
    bind();
  }
})();

// Auto-refresh while panel is open (and once on load to populate the badge)
function _startOptimizerPolling() {
  if (_optimizerPollTimer) return;
  _optimizerPollTimer = setInterval(() => {
    // Refresh badge in background even when panel is closed (every 5 min)
    if (_optimizerPanelOpen || (Date.now() - _optimizerLastRefresh) > 5 * 60 * 1000) {
      _refreshOptimizerPanel();
    }
  }, 60000);
  // Initial fetch so the badge count is accurate a moment after boot
  setTimeout(_refreshOptimizerPanel, 2500);
}
_startOptimizerPolling();

// Allow mobile_panels.js to keep the open-flag in sync when it portals the
// panel to <body> as a bottom sheet.
if (typeof window !== "undefined") {
  runtimeScope._setOptimizerPanelOpen = function (v) { _optimizerPanelOpen = !!v; };
}

// Close panel when clicking outside
document.addEventListener("click", (e) => {
  if (!_optimizerPanelOpen) return;
  const panel = document.getElementById("optimizerPanel");
  // On mobile the panel is portaled out of the badge into <body>; its own
  // backdrop (mobile_panels.js) owns closing, so skip the badge-based check.
  if (panel && panel.classList.contains("mobile-panel-portaled")) return;
  const badge = document.getElementById("optimizerBadge");
  if (badge && !badge.contains(/** @type {Node} */ (e.target))) {
    _optimizerPanelOpen = false;
    if (panel) panel.classList.remove("visible");
  }
});

/* ===== migrated source: update.js ===== */
/* ═══════════════════════════════════════════════════════════════════
   update.js — Self-update topbar button

   Renders a small "check for updates" button in the topbar. On load it
   silently checks the official GitHub repo for a newer release tag and,
   when one exists, shows a dot badge. Clicking opens a dialog that
   reports current → latest, then lets an admin apply the update
   (git pull --ff-only) and explicitly restart.

   ALL backend calls go through window.Api.update.* (see api.js) — this
   file never calls fetch() directly (CLAUDE.md §3.2.0).

   Concatenated by Vite's module graph — symbols share window scope.
   ═══════════════════════════════════════════════════════════════════ */

var _updateState = null;   // last /update/check payload
var _updateBusy = false;
var _updateTaskId = null;  // current apply task; push frames keyed on it
var _updateStageEls = null;// {fetch, pull, deps} → <li> step elements
var _updateStageState = {};   // stage → last frame seen (replays on modal re-open)
var _updateDoneResult = null; // terminal apply result awaiting the restart decision

// Ordered stages of an apply run, rendered as the live stepper.
var _UPDATE_STAGES = ['fetch', 'pull', 'deps'];

var _pendingRestartToastFor = null;  // version already toasted (once per page load)

/** Silent background check — called once at boot. Populates the badge.
 *  ALSO the reload-robust completion path: a download outlives the page, so
 *  the server persists the apply outcome — a landed update awaiting restart
 *  toasts the restart offer here even if the original page is long gone, and
 *  a still-running download gets its push subscription re-attached so the
 *  terminal frame still fires (and toasts) without the user re-opening the
 *  dialog. */
async function _updateBootCheck() {
  try {
    const r = await Api.update.check();
    if (!r || !r.ok) return;
    _updateState = r;
    _renderUpdateBadge();
    if (r.pending_restart && r.pending_restart.new_version) {
      _updateDoneResult = _doneResultFromPending(r.pending_restart);
      if (_pendingRestartToastFor !== r.pending_restart.new_version) {
        _pendingRestartToastFor = r.pending_restart.new_version;
        showToast('✅', t('update.bgDoneTitle').replace('%s', 'v' + r.pending_restart.new_version),
          t('update.bgDoneBody'), 30000,
          { hint: t('update.bgDoneHint'), onClick: function () { restartServer(); } });
      }
      return;
    }
    if (r.apply_in_progress && r.apply_in_progress.task_id && !_updateBusy) {
      _updateBusy = true;
      _updateTaskId = r.apply_in_progress.task_id;
      _subscribeUpdateProgress(r.apply_in_progress.task_id);
    }
  } catch (e) {
    if (typeof debugLog === 'function') debugLog('[Update] boot check failed: ' + (e && e.message), 'warning');
  }
}

/** Shape a /update/check pending_restart projection into the done-frame
 *  result dict the terminal-card renderer already understands. */
function _doneResultFromPending(p) {
  const depsFailed = !!(p.deps_changed && !p.deps_installed);
  return { ok: !depsFailed, changed: true, needs_restart: true,
           new_version: p.new_version || '', old_version: p.old_version || '',
           deps_changed: !!p.deps_changed, deps_installed: !!p.deps_installed,
           error: p.error || '', detail: p.detail || '' };
}

/** Render the terminal apply card: restart-to-apply on success, the
 *  deps-failed variant when code landed but pip install failed. */
function _renderDoneCard(r) {
  if (!r.ok) { _renderDepsFailed(r); return; }
  _renderUpdateDone(r);
}

/** Toggle the "update available" dot on the topbar button. */
function _renderUpdateBadge() {
  const btn = document.getElementById('updateBtn');
  if (!btn) return;
  const avail = !!(_updateState && _updateState.update_available);
  btn.classList.toggle('has-update', avail);
  if (avail && _updateState) {
    btn.title = t('update.availableTitle').replace('%s', _updateState.latest || '');
  } else {
    btn.title = t('update.checkTitle');
  }
  _renderSettingsUpdatePill();
}

/** Mirror the "update available" state onto the Settings › General card.
 *  The update entry point now lives there (the topbar button is a hidden
 *  stub), so the pill must follow the same state rather than being computed
 *  a second time — one source of truth, two surfaces. Safe to call before
 *  the settings panel is in the DOM; it simply no-ops. */
function _renderSettingsUpdatePill() {
  const pill = document.getElementById('settingsUpdatePill');
  if (!pill) return;
  pill.style.display = (_updateState && _updateState.update_available) ? '' : 'none';
}

/** Open the update dialog. Re-checks live so the dialog is never stale.
 *  EXCEPTION: an in-flight apply or a finished download awaiting the restart
 *  decision owns the modal body — restore THAT card instead of re-running the
 *  check, which would clobber the live stepper / restart prompt with the
 *  "checking…" spinner (the apply itself keeps running server-side, so the
 *  user would lose all visibility into it). */
async function openUpdateDialog() {
  const modal = document.getElementById('updateModal');
  if (!modal) return;
  modal.classList.add('open');
  if (_updateBusy) {
    _ensureUpdateScaffold();
    _renderUpdateStepper();
    _replayUpdateStageState();
    return;
  }
  if (_updateDoneResult) {
    _ensureUpdateScaffold();
    _renderDoneCard(_updateDoneResult);
    return;
  }
  _runUpdateCheck();
  _renderPendingLifecycleApprovals();
}

/** True when the update modal is currently visible. */
function _updateModalOpen() {
  const m = document.getElementById('updateModal');
  return !!(m && m.classList.contains('open'));
}

/** Ensure #updateModalBody carries the action-area scaffold the stepper and
 *  the done card render into. Closing the modal only hides it (the scaffold
 *  survives), but a fresh page or an interim re-render may have removed it —
 *  recreate it so a re-opened dialog never goes blank mid-apply /
 *  pending-restart. */
function _ensureUpdateScaffold() {
  const body = document.getElementById('updateModalBody');
  if (!body || document.getElementById('updateActionArea')) return;
  body.innerHTML =
    (_updateState ? _updateHeroHtml(_updateState) : '') +
    '<div class="upd-action" id="updateActionArea"></div>' +
    '<div id="updateLifecycleApprovals" style="display:none"></div>';
}

/** Run the version check with a visible spinner + bounded timeout.
 *  The check hits GitHub's tags API server-side; on a slow/blocked
 *  network we must NOT sit on a bare label forever — show a spinner,
 *  cap the wait, and surface the CONCRETE failure reason (never a vague
 *  "try again later"). */
async function _runUpdateCheck() {
  const body = document.getElementById('updateModalBody');
  if (!body) return;
  // A restart or an in-flight apply owns the modal body — re-opening the
  // dialog (or a retry click) must not paint the "checking…" spinner over
  // the live progress card.
  if (_restartActive || _updateBusy) return;
  body.innerHTML =
    '<div class="upd-checking-wrap"><span class="upd-big-spin"></span><span>' +
    escapeHtml(t('update.checking')) + '</span></div>';

  let r = null;
  let failure = null;  // {title, reason} — set on any failure
  try {
    // Bounded wait — the default 30s feels frozen. 12s is plenty for a
    // reachable GitHub; beyond that we surface a reason instead of hanging.
    // onError:'throw' (overriding api.js's default null) so we can read the
    // real cause — backend down vs HTTP error vs timeout — and say so.
    r = await Api.update.check({ timeout: 12000, onError: 'throw' });
  } catch (e) {
    failure = _classifyCheckError(e);
    if (typeof debugLog === 'function') debugLog('[Update] check failed: ' + (e && e.message), 'error');
  }

  // The request succeeded at the HTTP layer but the backend could not reach
  // GitHub — it tells us the concrete cause via error_kind/error_detail.
  if (!failure && r && r.error_kind) {
    failure = _githubFailureReason(r.error_kind, r.error_detail);
  }
  // Defensive: a malformed/empty payload with no explicit error.
  if (!failure && (!r || !r.ok)) {
    failure = { title: t('update.checkFailTitle'), reason: t('update.errUnknown') };
  }

  if (failure) {
    _renderCheckError(failure);
    return;
  }
  _updateState = r;
  _renderUpdateBadge();
  _renderUpdateDialogBody(r);
}

/** Map a thrown ApiError (backend side) to a concrete {title, reason}.
 *  Distinguishes "backend unreachable" / "request timed out" / "backend
 *  returned HTTP N" so the user always learns the real cause. */
function _classifyCheckError(e) {
  const title = t('update.checkFailTitle');
  // AbortController timeout (api.js) surfaces as AbortError or code 'timeout'.
  const code = e && e.code;
  const name = e && e.name;
  if (code === 'timeout' || name === 'AbortError') {
    return { title, reason: t('update.errTimeout') };
  }
  // Network-layer failure reaching our OWN backend (server down / restarting).
  if (code === 'network' || (typeof e !== 'undefined' && e instanceof TypeError)) {
    return { title, reason: t('update.errBackend') };
  }
  // HTTP error from the backend route itself (e.g. 500/502/auth).
  if (e && typeof e.status === 'number' && e.status > 0) {
    return { title, reason: t('update.errBackendHttp').replace('%s', String(e.status)) };
  }
  return { title, reason: t('update.errBackend') };
}

/** Map the backend's GitHub-side error_kind to localized {title, reason}. */
function _githubFailureReason(kind, detail) {
  const title = t('update.checkFailTitle');
  const map = {
    network: t('update.errNetwork'),
    rate_limited: t('update.errRateLimited'),
    http: t('update.errHttp').replace('%s', escapeHtml(String(detail || '').replace(/^HTTP\s*/i, '').split(' ')[0] || '')),
    parse: t('update.errParse'),
    no_tags: t('update.errNoTags'),
  };
  return { title, reason: map[kind] || t('update.errUnknown'), detail: detail };
}

/** Render a concrete error card: heading + the real reason + retry.
 *  Always names WHY the check failed — backend down, timeout, GitHub
 *  unreachable, rate-limited, etc. */
function _renderCheckError(failure) {
  const body = document.getElementById('updateModalBody');
  if (!body) return;
  const icon =
    '<span class="upd-err-icon"><svg width="22" height="22" viewBox="0 0 24 24" ' +
    'fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" ' +
    'stroke-linejoin="round"><circle cx="12" cy="12" r="10"/>' +
    '<line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg></span>';
  body.innerHTML =
    '<div class="upd-err-card">' +
      '<div class="upd-err-head">' + icon +
        '<div class="upd-err-title">' + escapeHtml(failure.title || t('update.checkFailTitle')) + '</div>' +
      '</div>' +
      '<p class="upd-err-reason">' + escapeHtml(failure.reason || t('update.errUnknown')) + '</p>' +
      '<button class="upd-retry-btn" data-tofu-action="_runUpdateCheck()">' +
        '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" ' +
        'stroke-width="2" stroke-linecap="round" stroke-linejoin="round">' +
        '<path d="M23 4v6h-6"/><path d="M20.49 15a9 9 0 1 1-2.12-9.36L23 10"/></svg>' +
        escapeHtml(t('update.retry')) + '</button>' +
    '</div>';
}

/** current → latest version hero card. */
function _updateHeroHtml(r) {
  const upToDate = !r.update_available;
  const cur = 'v' + escapeHtml(r.current || '?');
  const latest = r.latest ? 'v' + escapeHtml(r.latest) : '—';
  const arrow = '<span class="upd-arrow"><svg width="20" height="20" viewBox="0 0 24 24" ' +
    'fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" ' +
    'stroke-linejoin="round"><line x1="5" y1="12" x2="19" y2="12"/>' +
    '<polyline points="12 5 19 12 12 19"/></svg></span>';
  return '<div class="upd-hero' + (upToDate ? ' up-to-date' : '') + '">' +
    '<div class="upd-ver"><span class="upd-ver-label">' + escapeHtml(t('update.current')) +
    '</span><span class="upd-ver-num">' + cur + '</span></div>' +
    arrow +
    '<div class="upd-ver latest"><span class="upd-ver-label">' + escapeHtml(t('update.latest')) +
    '</span><span class="upd-ver-num">' + latest + '</span></div>' +
  '</div>';
}

function _renderUpdateDialogBody(r) {
  const body = document.getElementById('updateModalBody');
  if (!body) return;

  // Server-persisted apply outcomes outrank the fresh-check view: a landed
  // update awaiting restart shows the restart card; a download still running
  // (started before a page reload) re-attaches the live stepper — otherwise
  // the user would be offered a SECOND, duplicate 50MB+ download.
  if (r.pending_restart && r.pending_restart.new_version) {
    _updateDoneResult = _doneResultFromPending(r.pending_restart);
    body.innerHTML =
      _updateHeroHtml(r) +
      '<div class="upd-action" id="updateActionArea"></div>' +
      '<div id="updateLifecycleApprovals" style="display:none"></div>';
    _renderDoneCard(_updateDoneResult);
    return;
  }
  if (r.apply_in_progress && r.apply_in_progress.task_id && !_updateBusy) {
    _updateBusy = true;
    _updateStageState = {};
    _updateDoneResult = null;
    body.innerHTML =
      _updateHeroHtml(r) +
      '<div class="upd-action" id="updateActionArea"></div>' +
      '<div id="updateLifecycleApprovals" style="display:none"></div>';
    _renderUpdateStepper();
    _subscribeUpdateProgress(r.apply_in_progress.task_id);
    return;
  }

  let actionHtml = '';
  if (!r.update_available) {
    actionHtml = '<div class="upd-badge ok"><span class="upd-badge-icon">' +
      '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" ' +
      'stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round">' +
      '<polyline points="20 6 9 17 4 12"/></svg></span><span>' +
      escapeHtml(t('update.upToDate').replace(/^✅\s*/, '')) + '</span></div>';
  } else if (r.dirty) {
    // Genuine tracked-source edits block the pull. List a few, never auto-stash.
    const sample = (r.blocking || []).slice(0, 8).map(escapeHtml).join('<br>');
    actionHtml =
      '<div class="upd-badge warn"><span class="upd-badge-icon"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m21.73 18-8-14a2 2 0 0 0-3.48 0l-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.73-3"/><path d="M12 9v4"/><path d="M12 17h.01"/></svg></span><span>' +
      escapeHtml(t('update.dirty')) + '</span></div>' +
      (sample ? '<pre class="upd-files">' + sample + '</pre>' : '');
  } else {
    // A non-git deployment (exported copy / zip) updates via a downloaded
    // release-tarball overlay rather than git pull. Note the method so the
    // user understands the one limitation (can't delete files removed upstream).
    const methodNote = (r.update_method === 'tarball')
      ? '<p class="upd-hint">' + escapeHtml(t('update.tarballNote')) + '</p>'
      : '';
    actionHtml =
      '<p class="upd-ready">' + escapeHtml(t('update.ready')) + '</p>' +
      methodNote +
      '<button class="upd-apply-btn" id="updateApplyBtn" data-tofu-action="applyUpdate()">' +
      '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" ' +
      'stroke-linecap="round" stroke-linejoin="round"><path d="M12 3v12"/>' +
      '<polyline points="7 10 12 15 17 10"/><path d="M5 21h14"/></svg>' +
      escapeHtml(t('update.applyBtn')) + '</button>';
  }

  body.innerHTML =
    _updateHeroHtml(r) +
    '<div class="upd-action" id="updateActionArea">' + actionHtml + '</div>' +
    '<div id="updateLifecycleApprovals" style="display:none"></div>';
  _renderPendingLifecycleApprovals();
}

/** Render the live stepper (one row per stage) into the action area. */
function _renderUpdateStepper() {
  const area = document.getElementById('updateActionArea');
  if (!area) return;
  const isTarball = !!(_updateState && _updateState.update_method === 'tarball');
  const labels = {
    fetch: isTarball ? t('update.step.fetchDl') : t('update.step.fetch'),
    pull: isTarball ? t('update.step.pullOverlay') : t('update.step.pull'),
    deps: t('update.step.deps'),
  };
  const items = _UPDATE_STAGES.map(function (stage) {
    return '<li class="upd-step" data-stage="' + stage + '">' +
      '<span class="upd-step-dot"></span>' +
      '<span class="upd-step-label">' + escapeHtml(labels[stage]) + '</span>' +
      '<span class="upd-step-detail"></span></li>';
  }).join('');
  area.innerHTML = '<ul class="upd-stepper">' + items + '</ul>' +
    '<p class="upd-hint">' + escapeHtml(t('update.bgHint')) + '</p>';
  _updateStageEls = {};
  _UPDATE_STAGES.forEach(function (stage) {
    _updateStageEls[stage] = area.querySelector('.upd-step[data-stage="' + stage + '"]');
  });
}

/** Apply a {stage,status,detail,pct,loaded,total,speed} frame to the stepper.
 *  A stage may report determinate progress (fetch download with a
 *  Content-Length → pct 0-100) or indeterminate activity (pip install lines,
 *  git object counting with no total). We render a thin per-step bar so a
 *  long-running stage NEVER looks frozen: determinate fills to pct, otherwise
 *  it shows an animated indeterminate sweep. */
function _applyStageFrame(frame) {
  // Remember the last frame per stage so the stepper can be rebuilt exactly
  // when the modal is closed mid-apply and re-opened later.
  if (frame && frame.stage) _updateStageState[frame.stage] = frame;
  if (!_updateStageEls) return;
  const el = _updateStageEls[frame.stage];
  if (!el) return;
  el.classList.remove('is-active', 'is-done', 'is-error');
  if (frame.status === 'active') {
    el.classList.add('is-active');
  } else if (frame.status === 'done') {
    el.classList.add('is-done');
    _setStepBar(el, null, false);  // clear the bar on completion
  } else if (frame.status === 'skip') {
    el.classList.add('is-done');
    _setStepBar(el, null, false);
    const lbl = el.querySelector('.upd-step-label');
    if (lbl) lbl.textContent = t('update.step.depsSkip');
  } else if (frame.status === 'error') {
    el.classList.add('is-error');
    _setStepBar(el, null, false);
  }
  const det = el.querySelector('.upd-step-detail');
  if (det && frame.detail && frame.status !== 'error') det.textContent = frame.detail;

  // Live progress bar while a stage is active.
  if (frame.status === 'active') {
    if (typeof frame.pct === 'number' && frame.pct >= 0) {
      _setStepBar(el, Math.max(0, Math.min(100, frame.pct)), false);
    } else {
      // No total → indeterminate sweep (still visibly "working").
      _setStepBar(el, null, true);
    }
  }
}

/** Ensure a stage row carries a <div class="upd-step-bar"> and drive it.
 *  pct=number → determinate width; indeterminate=true → animated sweep;
 *  pct=null & indeterminate=false → remove the bar entirely. */
function _setStepBar(el, pct, indeterminate) {
  let wrap = el.querySelector('.upd-step-bar');
  if (pct === null && !indeterminate) {
    if (wrap) wrap.remove();
    return;
  }
  if (!wrap) {
    wrap = document.createElement('div');
    wrap.className = 'upd-step-bar';
    wrap.innerHTML = '<div class="upd-step-bar-fill"></div>';
    el.appendChild(wrap);
  }
  const fill = wrap.querySelector('.upd-step-bar-fill');
  if (!fill) return;
  if (indeterminate) {
    wrap.classList.add('is-indeterminate');
    fill.style.width = '';
  } else {
    wrap.classList.remove('is-indeterminate');
    fill.style.width = pct.toFixed(1) + '%';
  }
}

/** Re-render a freshly-built stepper to the last known state of every
 *  stage (used when the dialog re-opens mid-apply). */
function _replayUpdateStageState() {
  _UPDATE_STAGES.forEach(function (stage) {
    const fr = _updateStageState[stage];
    if (fr) _applyStageFrame(fr);
  });
}

/** Kick off the update. The backend runs it in a background thread and
 *  streams stage progress over the 'update' push channel; we render a live
 *  stepper and act on the terminal 'done' frame. This keeps the modal
 *  responsive no matter how long git pull / pip install takes. The modal may
 *  be CLOSED at any point — the download continues server-side regardless and
 *  the terminal frame raises a toast (see _onUpdateDone). */
async function applyUpdate() {
  if (_updateBusy) return;
  _updateBusy = true;
  _updateStageState = {};
  _updateDoneResult = null;

  // Swap the action area to the live stepper immediately so the UI never
  // appears frozen between the click and the first push frame.
  _renderUpdateStepper();
  if (_updateStageEls && _updateStageEls.fetch) {
    _updateStageEls.fetch.classList.add('is-active');
  }

  let r = null;
  try {
    r = await Api.update.apply();
  } catch (e) {
    const msg = (e && e.message) || t('update.applyStartFailed');
    _showUpdateError(msg);
    if (typeof debugLog === 'function') debugLog('[Update] apply start failed: ' + msg, 'error');
    _updateBusy = false;
    return;
  }

  if (!r || !r.taskId) {
    _showUpdateError(t('update.applyStartFailed'));
    _updateBusy = false;
    return;
  }

  _updateTaskId = r.taskId;
  _subscribeUpdateProgress(r.taskId);
}

/** Subscribe to the apply task's push channel; route stage + done frames. */
function _subscribeUpdateProgress(taskId) {
  if (typeof pushSubscribe !== 'function') {
    // No WebSocket layer — without it we can't observe progress. Tell the
    // user the update is running server-side and to refresh shortly.
    _showUpdateError(t('update.applyStartFailed'));
    _updateBusy = false;
    return;
  }
  // Safety net: if no frame ever lands (server died / channel wedged),
  // surface a timeout instead of an eternal spinner. When the modal is closed
  // the in-dialog error is invisible — raise a toast as well.
  const _onWatchdog = function () {
    _finishUpdateSub(taskId);
    _showUpdateError(t('update.applyTimeout'));
    if (!_updateModalOpen()) {
      showToast('⚠️', t('update.bgFailTitle'), t('update.applyTimeout'), 8000);
    }
    _updateBusy = false;
  };
  let watchdog = setTimeout(_onWatchdog, 15 * 60 * 1000);

  const handler = function (frame) {
    if (!frame || frame.taskId !== taskId) return;
    clearTimeout(watchdog);
    watchdog = setTimeout(_onWatchdog, 15 * 60 * 1000);

    if (frame.type === 'stage') {
      _applyStageFrame(frame);
      return;
    }
    if (frame.type === 'done') {
      clearTimeout(watchdog);
      _finishUpdateSub(taskId);
      _updateBusy = false;
      _onUpdateDone(frame);
    }
  };
  _updateActiveHandler = handler;
  pushSubscribe('update', taskId, handler);
}

var _updateActiveHandler = null;
function _finishUpdateSub(taskId) {
  if (typeof pushUnsubscribe === 'function' && _updateActiveHandler) {
    pushUnsubscribe('update', taskId, _updateActiveHandler);
  }
  _updateActiveHandler = null;
}

/** Terminal 'done' frame — mirror the apply_update() result dict.
 *  The modal may be closed (background apply): the restart decision is then
 *  surfaced as a toast whose click fires the same restart flow the in-dialog
 *  button would, and the result is kept in _updateDoneResult so re-opening
 *  the dialog still shows the restart card. */
function _onUpdateDone(r) {
  const area = document.getElementById('updateActionArea');
  _updateStageState = {};   // terminal — no live frames left to replay
  if (!r.ok) {
    // Code WAS pulled but pip install failed → still offer a restart.
    if (r.changed && r.deps_changed && !r.deps_installed) {
      _updateDoneResult = r;
      _renderDepsFailed(r);
    } else {
      _showUpdateError(r.error || t('update.applyFailed'), r.detail || r.deps_detail || '');
    }
    if (!_updateModalOpen()) {
      showToast('⚠️', t('update.bgFailTitle'), (r.error || t('update.applyFailed')),
        8000, { hint: t('update.bgFailHint'), onClick: function () { openUpdateDialog(); } });
    }
    if (typeof debugLog === 'function') {
      debugLog('[Update] apply failed: ' + (r.error || ''), 'error');
    }
    return;
  }

  if (!r.changed) {
    if (area) {
      area.innerHTML = '<div class="upd-badge ok"><span class="upd-badge-icon">' +
        '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" ' +
        'stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round">' +
        '<polyline points="20 6 9 17 4 12"/></svg></span><span>' +
        escapeHtml(t('update.upToDate').replace(/^✅\s*/, '')) + '</span></div>';
    }
    return;
  }

  // Pulled new code — needs an explicit restart to take effect.
  _updateDoneResult = r;
  _renderUpdateDone(r);
  if (!_updateModalOpen()) {
    showToast('✅', t('update.bgDoneTitle').replace('%s', 'v' + (r.new_version || '')),
      t('update.bgDoneBody'), 30000,
      { hint: t('update.bgDoneHint'), onClick: function () { restartServer(); } });
  }
}

/** Render the post-download "restart to apply" card (shared by the live done
 *  frame and a re-opened dialog). */
function _renderUpdateDone(r) {
  const area = document.getElementById('updateActionArea');
  if (!area) return;
  const depsNote = (r.deps_changed && r.deps_installed)
    ? '<p class="upd-uptodate">' + escapeHtml(t('update.depsInstalled')) + '</p>'
    : '';
  area.innerHTML =
    '<p class="upd-ready">' + escapeHtml(t('update.pulled').replace('%s', 'v' + (r.new_version || ''))) + '</p>' +
    depsNote +
    '<button class="upd-apply-btn" id="updateRestartBtn" data-tofu-action="restartServer()">' +
    '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" ' +
    'stroke-linecap="round" stroke-linejoin="round"><path d="M23 4v6h-6"/>' +
    '<path d="M20.49 15a9 9 0 1 1-2.12-9.36L23 10"/></svg>' +
    escapeHtml(t('update.restartBtn')) + '</button>' +
    '<p class="upd-hint">' + escapeHtml(t('update.restartHint')) + '</p>';
}

/** Build a full, scrollable log block with a "copy" button.
 *  The COMPLETE text is shown verbatim (never truncated) so the operator can
 *  read and copy-paste the whole error — the reported gap was a mangled tail.
 *  The raw log is stashed on the element (dataset) so the copy button lifts
 *  the exact bytes, not the HTML-escaped/DOM-reflowed version. */
function _updateLogBlockHtml(logText) {
  const text = String(logText || '');
  if (!text) return '';
  // Base64-stash the raw log so the copy handler recovers exact bytes without
  // re-reading escaped DOM text (encodeURIComponent handles any UTF-8).
  let stash = '';
  try { stash = btoa(unescape(encodeURIComponent(text))); } catch (e) { stash = ''; }
  const copyIcon =
    '<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" ' +
    'stroke-width="2" stroke-linecap="round" stroke-linejoin="round">' +
    '<rect x="9" y="9" width="13" height="13" rx="2" ry="2"/>' +
    '<path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/></svg>';
  return '<div class="upd-log" data-log="' + escapeHtml(stash) + '">' +
    '<div class="upd-log-head">' +
      '<span class="upd-log-label">' + escapeHtml(t('update.logLabel')) + '</span>' +
      '<button type="button" class="upd-log-copy" data-tofu-action="_copyUpdateLog(this)">' +
        copyIcon + '<span class="upd-log-copy-txt">' + escapeHtml(t('update.copyLog')) + '</span>' +
      '</button>' +
    '</div>' +
    '<pre class="upd-files upd-log-pre">' + escapeHtml(text) + '</pre>' +
  '</div>';
}

/** Copy the full raw log of the nearest .upd-log block to the clipboard. */
function _copyUpdateLog(btn) {
  const wrap = btn && btn.closest ? btn.closest('.upd-log') : null;
  if (!wrap) return;
  let text = '';
  try { text = decodeURIComponent(escape(atob(wrap.dataset.log || ''))); }
  catch (e) { text = (wrap.querySelector('.upd-log-pre') || {}).textContent || ''; }
  const done = function () {
    const txt = btn.querySelector('.upd-log-copy-txt');
    const orig = txt ? txt.textContent : '';
    if (txt) txt.textContent = t('update.logCopied');
    btn.classList.add('copied');
    setTimeout(function () {
      btn.classList.remove('copied');
      if (txt) txt.textContent = orig;
    }, 1500);
  };
  if (typeof _safeClipboardWrite === 'function') {
    _safeClipboardWrite(text).then(done).catch(function () {});
  } else if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(text).then(done).catch(function () {});
  }
}

/** Render a terminal error message in the action area.
 *  When a diagnostic ``detail`` log is available (e.g. an unexpected apply
 *  failure), show it IN FULL with a copy button so the user can paste it. */
function _showUpdateError(msg, detail) {
  const area = document.getElementById('updateActionArea');
  if (!area) return;
  area.innerHTML =
    '<p class="upd-error">' + escapeHtml(String(msg)) + '</p>' +
    _updateLogBlockHtml(detail);
}

/** Code was pulled but pip install failed — explain + still allow restart.
 *  Shows the COMPLETE dependency-install log (no truncation) with a copy
 *  button so the operator can paste the whole error verbatim. */
function _renderDepsFailed(b) {
  const area = document.getElementById('updateActionArea');
  if (!area) return;
  area.innerHTML =
    '<p class="upd-warn">' + escapeHtml(t('update.depsFailed').replace('%s', 'v' + (b.new_version || ''))) + '</p>' +
    _updateLogBlockHtml(b.deps_detail || '') +
    '<button class="upd-apply-btn" id="updateRestartBtn" data-tofu-action="restartServer()">' +
    escapeHtml(t('update.restartBtn')) + '</button>' +
    '<p class="upd-hint">' + escapeHtml(t('update.restartHint')) + '</p>';
}

// ── Restart progress model ───────────────────────────────────────────
// During an in-place re-exec there is NO server listening (the old process
// os.execv's into the new one; Hypercorn only binds after DB init + import
// validation + service startup). So we can't stream live boot logs over the
// wire. Instead we drive a determinate bar through the server's REAL boot
// phases (mirrors server.py's _boot() sequence), time-estimated, and treat
// /api/health as the single source of truth: the instant it answers we snap
// to 100% with the genuine returned version. The bar eases toward each
// phase's cap but never reaches 100% on its own — it can only *under*-report
// progress, never claim "done" before the server actually is.
var _RESTART_PHASES = [
  { key: 'shutdown', dur: 1.5, to: 12 },  // graceful drain + os.execv
  { key: 'reload',   dur: 3.0, to: 34 },  // re-import core modules
  { key: 'db',       dur: 2.5, to: 52 },  // init_db / warmup
  { key: 'imports',  dur: 3.0, to: 72 },  // critical-import validation
  { key: 'services', dur: 3.0, to: 86 },  // background workers / MCP
  { key: 'bind',     dur: 6.0, to: 94 },  // _wait_port_free + Hypercorn bind
];
var _restartT0 = 0;
var _restartRaf = null;
var _restartPoll = null;
var _restartDone = false;
// The server's bootId captured BEFORE we trigger the restart. The re-exec
// mints a fresh bootId (os.execv keeps the PID + start-time, so bootId is the
// only reliable 'a NEW process answered' signal). _restartCheckHealth only
// declares success when health returns a DIFFERENT bootId — so the OLD process
// still answering during the drain window is never mistaken for a done restart.
var _restartPreBootId = null;
// The server's codeFingerprint.digest captured BEFORE the restart. After the
// re-exec, the fresh process recomputes it from the source it actually loaded
// (HEAD + uncommitted tracked edits). Comparing pre vs post lets us tell the
// operator not just "a new process answered" (bootId) but whether that process
// loaded DIFFERENT source — i.e. whether their edits are actually live. null
// when the server can't produce one (non-git deploy) → degrade to bootId only.
var _restartPreFingerprint = null;
// True from the moment a restart is kicked off until it succeeds or times
// out. Single source of truth that the dialog-render paths consult so they
// never clobber the live restart progress card (e.g. re-opening the dialog
// or the always-live footer "Restart now" button mid-restart). Distinct from
// _restartDone, which starts false and so can't tell "not started" from "done".
var _restartActive = false;

/** Map elapsed seconds → {pct, key} along the phase timeline (ease-out per
 *  phase). The final phase holds at its cap if the server overruns, so a
 *  slow boot looks "still working" rather than falsely complete. */
function _restartProgress(elapsed) {
  var from = 0, acc = 0;
  for (var i = 0; i < _RESTART_PHASES.length; i++) {
    var ph = _RESTART_PHASES[i];
    var last = (i === _RESTART_PHASES.length - 1);
    if (elapsed < acc + ph.dur || last) {
      var t = Math.min(1, (elapsed - acc) / ph.dur);
      var eased = 1 - Math.pow(1 - t, 2);
      return { pct: Math.min(from + (ph.to - from) * eased, ph.to), key: ph.key };
    }
    acc += ph.dur; from = ph.to;
  }
  return { pct: 94, key: 'bind' };
}

/** Render the restart progress card into the dialog body. */
function _renderRestartProgress() {
  const body = document.getElementById('updateModalBody');
  if (!body) return;
  body.innerHTML =
    '<div class="upd-restart" id="updRestartCard">' +
      '<div class="upd-restart-head">' +
        '<span class="upd-restart-spin" id="updRestartSpin"></span>' +
        '<div class="upd-restart-headtext">' +
          '<div class="upd-restart-title" id="updRestartTitle">' + escapeHtml(t('update.restartTitle')) + '</div>' +
          '<div class="upd-restart-sub">' + escapeHtml(t('update.restartSub')) + '</div>' +
        '</div>' +
      '</div>' +
      '<div class="upd-restart-bar"><div class="upd-restart-fill" id="updRestartFill"></div></div>' +
      '<div class="upd-restart-foot">' +
        '<span class="upd-restart-phase" id="updRestartPhase">' + escapeHtml(t('update.phase.shutdown')) + '</span>' +
        '<span class="upd-restart-pct" id="updRestartPct">0%</span>' +
      '</div>' +
    '</div>';
}

/** Animation frame: advance the bar from the phase timeline. */
function _restartAnimate() {
  if (_restartDone) return;
  const elapsed = (Date.now() - _restartT0) / 1000;
  const p = _restartProgress(elapsed);
  const fill = document.getElementById('updRestartFill');
  const pctEl = document.getElementById('updRestartPct');
  const phaseEl = document.getElementById('updRestartPhase');
  if (fill) fill.style.width = p.pct.toFixed(1) + '%';
  if (pctEl) pctEl.textContent = Math.round(p.pct) + '%';
  if (phaseEl) {
    const label = t('update.phase.' + p.key);
    const secs = ' · ' + t('update.restartElapsed').replace('%s', String(Math.round(elapsed)));
    phaseEl.textContent = label + secs;
  }
  _restartRaf = requestAnimationFrame(_restartAnimate);
}

/** Snap to 100% "Back online · vX", then reload the page. */
function _restartSucceed(version, info) {
  if (_restartDone) return;
  _restartDone = true;
  _restartActive = false;
  if (_restartRaf) cancelAnimationFrame(_restartRaf);
  if (_restartPoll) clearInterval(_restartPoll);
  const fill = document.getElementById('updRestartFill');
  const pctEl = document.getElementById('updRestartPct');
  const phaseEl = document.getElementById('updRestartPhase');
  const spin = document.getElementById('updRestartSpin');
  const card = document.getElementById('updRestartCard');
  if (card) card.classList.add('is-online');
  if (spin) spin.classList.add('is-done');
  if (fill) fill.style.width = '100%';
  if (pctEl) pctEl.textContent = '100%';
  if (phaseEl) {
    phaseEl.textContent = t('update.phase.online') +
      (version ? ' · v' + version : '');
  }
  // Surface whether the fresh process actually loaded DIFFERENT source. A
  // 'unchanged' verdict is the useful safety signal: the restart succeeded
  // (new process) yet loaded byte-identical source — a heads-up that the
  // operator's edits did NOT reach the running server (e.g. edited a different
  // checkout, or the diff was reverted). 'changed' confirms edits are live.
  const verdict = _restartCodeVerdict(info);
  if (verdict === 'unchanged') {
    showToast('⚠️', t('update.codeUnchangedTitle'), t('update.codeUnchangedHint'), 8000);
    if (typeof debugLog === 'function') debugLog('[Update] restart: new process but source unchanged (edits not applied?)', 'warning');
  } else if (verdict === 'changed') {
    if (typeof debugLog === 'function') debugLog('[Update] restart: new source loaded (edits are live)', 'success');
  }
  // Brief pause so the user sees the completed state before the reload.
  setTimeout(function () { window.location.reload(); }, 750);
}

/** Restart failed to come back within the ceiling — stop and tell the user. */
function _restartTimeout() {
  if (_restartDone) return;
  _restartDone = true;
  _restartActive = false;
  if (_restartRaf) cancelAnimationFrame(_restartRaf);
  if (_restartPoll) clearInterval(_restartPoll);
  const phaseEl = document.getElementById('updRestartPhase');
  const spin = document.getElementById('updRestartSpin');
  if (spin) spin.classList.add('is-error');
  if (phaseEl) phaseEl.textContent = t('update.restartTimeout');
  showToast('⚠️', t('update.restartTimeout'), '', 6000);
}

/** Explicit restart — re-execs the server, then waits for it to come back.
 *  Invoked from the post-pull "Restart now" button AND the always-available
 *  footer button (no git pull needed). The backend re-execs in place via
 *  os.execv reclaiming the SAME port, so the page can reconnect to the same
 *  URL once /api/health answers again. */
async function restartServer(opts) {
  // Already restarting — ignore a re-entry (footer button stays live, the
  // post-pull button could be double-clicked) so we never spawn a second
  // poll loop or reset the progress timeline.
  if (_restartActive) return;
  _restartActive = true;
  const btn = document.getElementById('updateRestartBtn')
    || document.getElementById('updateRestartNowBtn');
  const _restoreBtn = function () {
    if (btn) { btn.disabled = false; btn.textContent = t('update.restartBtn'); }
  };
  if (btn) { btn.disabled = true; btn.textContent = t('update.restarting'); }

  // Human-approval gate (pt_40d00fd526e5479a): a restart POST without an
  // approvalId only REGISTERS a pending request (202). The human's click on
  // this very button IS the approval gesture, so we approve the pending
  // request immediately and retry with the token — the flow stays seamless
  // for the operator while agent shells (no UI, no gesture) stay gated.
  // A pre-approved id (from the pending-approvals card) rides in via opts.
  var _approvalId = (opts && opts.approvalId) || '';
  async function _requestRestart(forceFlag) {
    const payload = { convId: _ownConv };
    if (forceFlag) payload.force = true;
    if (_approvalId) payload.approvalId = _approvalId;
    const r = await Api.update.restart(payload);
    if (r && r.pendingApproval) {
      _approvalId = r.pendingApproval.id;
      await Api.update.decideLifecycleApproval(_approvalId, true);
      return _requestRestart(forceFlag);
    }
    return r;
  }

  // Capture the CURRENT process's bootId first, so we can require the
  // post-restart health to report a DIFFERENT one (proof a new process
  // answered). Best-effort: if this probe fails we fall back to null, and the
  // success rule then accepts any bootId-bearing health (still better than the
  // old 'any ok' rule) — see _restartCheckHealth.
  _restartPreBootId = null;
  _restartPreFingerprint = null;
  try {
    const pre = await Api.health.info();
    if (pre && pre.bootId) _restartPreBootId = pre.bootId;
    if (pre && pre.codeFingerprint && pre.codeFingerprint.digest) {
      _restartPreFingerprint = pre.codeFingerprint.digest;
    }
  } catch (e) { _restartPreBootId = null; _restartPreFingerprint = null; }

  // Our own conversation id — the backend excludes it when counting in-flight
  // tasks, so the running-task count reflects only OTHER conversations a
  // restart would interrupt (never counts our own idle conv against us).
  var _ownConv = '';
  try { _ownConv = activeConvId || ''; } catch (_e) { _ownConv = ''; }

  // Two-stage informed restart. Stage 1: request WITHOUT force. The backend
  // 409s with {needsForce, runningTasks} only when OTHER conversations have
  // in-flight tasks a restart would kill; an idle server accepts the
  // force-less call immediately (no confirm). Only on that 409 do we surface a
  // themed confirm NAMING the running-task count and, on explicit consent,
  // retry WITH force. This replaces the old blind generic pre-flight confirm
  // (so there is no double-confirm) and never silently kills sibling tasks.
  var _triggered = false;
  try {
    await _requestRestart(false);
    _triggered = true;
  } catch (e) {
    if (e && e.status === 429) {
      // Cooldown: the server was restarted moments ago — surface the
      // remaining seconds and stay put (NO progress card, nothing fired).
      const secs = (e.body && e.body.retryAfterSec) || '?';
      showToast('⏳', t('update.restartCooldown').replace('%s', String(secs)), '', 6000);
      _restartActive = false;
      _restoreBtn();
      return;
    }
    if (e && (e.status === 400 || e.status === 403 || e.status === 404)) {
      // Approval rejected/expired — definitive refusal, nothing is scheduled.
      showToast('⚠️', (e && e.message) || t('update.errUnknown'), '', 6000);
      if (typeof debugLog === 'function') debugLog('[Update] restart refused: HTTP ' + e.status + ' ' + (e && e.message), 'warning');
      _restartActive = false;
      _restoreBtn();
      return;
    }
    if (e && e.status === 409 && e.body && e.body.needsForce) {
      const count = (e.body.runningTasks || []).length;
      const ok = await showConfirm(
        t('update.restartForceConfirm').replace('%s', String(count)),
        { danger: true });
      if (!ok) {
        // Declined — deny the still-unconsumed approval so a stray approved
        // token cannot be fired later, then abort cleanly.
        if (_approvalId) {
          try { await Api.update.decideLifecycleApproval(_approvalId, false); } catch (_e) { /* best effort */ }
        }
        _restartActive = false;
        _restoreBtn();
        return;
      }
      try {
        await _requestRestart(true);
      } catch (e2) {
        if (typeof debugLog === 'function') debugLog('[Update] forced restart request failed: ' + (e2 && e2.message), 'warning');
      }
      // The re-exec is scheduled server-side (daemon thread) before the
      // response, so even a read error on the response means it is underway.
      _triggered = true;
    } else {
      // Non-guard error (e.g. a network blip while the backend already
      // scheduled the fire-and-forget re-exec). Proceed to the health-poll
      // rather than abort — the poll is the source of truth for "came back".
      if (typeof debugLog === 'function') debugLog('[Update] restart request failed: ' + (e && e.message), 'warning');
      _triggered = true;
    }
  }
  if (!_triggered) { _restartActive = false; _restoreBtn(); return; }

  _renderRestartProgress();
  _restartDone = false;
  _restartT0 = Date.now();
  _restartRaf = requestAnimationFrame(_restartAnimate);
  // Wait out the backend's 0.6s pre-exec sleep before the first probe so we
  // never mistake the still-alive OLD process for a successful restart.
  setTimeout(function () { _restartPoll = setInterval(_restartCheckHealth, 1500); }, 2500);
}

/** Manual graceful shutdown — writes the manual-shutdown marker so the next
 *  boot won't mistake this for an OS kill, then stops the server (no re-exec,
 *  so it does NOT come back on its own). Admin-only; always confirms. */
async function shutdownServer(opts) {
  if (_restartActive) return;   // a restart already owns the modal body
  if (!await showConfirm(t('update.shutdownConfirm'), { danger: true })) return;
  const rBtn = document.getElementById('updateRestartNowBtn');
  const sBtn = document.getElementById('updateShutdownBtn');
  if (rBtn) rBtn.disabled = true;
  if (sBtn) { sBtn.disabled = true; }
  await _fireShutdown((opts && opts.approvalId) || '');
}

/** Fire the shutdown through the approval gate (shared by the button and
 *  the pending-approvals card). The confirm click IS the human gesture, so
 *  a freshly-pended request is approved immediately and retried. */
async function _fireShutdown(approvalId) {
  try {
    const payload = approvalId ? { approvalId: approvalId } : {};
    const r = await Api.update.shutdown(payload);
    if (r && r.pendingApproval) {
      await Api.update.decideLifecycleApproval(r.pendingApproval.id, true);
      await Api.update.shutdown({ approvalId: r.pendingApproval.id });
    }
  } catch (e) {
    if (typeof debugLog === 'function') debugLog('[Shutdown] request failed: ' + (e && e.message), 'warning');
  }
  const body = document.getElementById('updateModalBody');
  if (body) {
    body.innerHTML =
      '<div class="upd-checking-wrap"><span>' +
      escapeHtml(t('update.shuttingDown')) + '</span></div>';
  }
  showToast('◐', t('update.shuttingDown'), t('update.shutdownHint'), 8000);
}

// ── Pending lifecycle approvals (agent-initiated restart/shutdown requests) ──
// An agent curl against /api/v1/update/restart|shutdown now ONLY registers a
// pending request; the human reviews the queue here and approves/denies.
// Approving executes the action immediately through the same UX as the
// operator's own button (force-confirm on running tasks included).
async function _renderPendingLifecycleApprovals() {
  const host = document.getElementById('updateLifecycleApprovals');
  if (!host) return;
  let records = [];
  try {
    const r = await Api.update.listLifecycleApprovals({ status: 'pending' });
    records = (r && r.records) || [];
  } catch (e) { records = []; }
  if (!records.length) {
    host.innerHTML = '';
    host.style.display = 'none';
    return;
  }
  host.style.display = '';
  host.innerHTML = '<div class="upd-lc-card">' +
    '<div class="upd-lc-title">' + escapeHtml(t('update.pendingApprovals')) + '</div>' +
    records.map(function (rec) {
      const o = rec.origin || {};
      let when = '';
      try { when = new Date((rec.requested_at || 0) * 1000).toLocaleTimeString(); } catch (_e) { when = ''; }
      const meta = [o.ua, o.conv_id, o.remote_addr].filter(Boolean).join(' · ');
      const btnLabel = rec.action === 'shutdown'
        ? t('update.approveExecuteShutdown') : t('update.approveExecuteRestart');
      return '<div class="upd-lc-row" data-id="' + escapeHtml(rec.id) +
        '" data-action="' + escapeHtml(rec.action) + '">' +
        '<div class="upd-lc-meta"><span class="upd-lc-action">' + escapeHtml(rec.action) +
        '</span> · ' + escapeHtml(when) + (meta ? ' · ' + escapeHtml(meta) : '') + '</div>' +
        '<div class="upd-lc-btns">' +
        '<button class="upd-lc-approve" data-tofu-action="_lcDecide(this,true)">' + escapeHtml(btnLabel) + '</button>' +
        '<button class="upd-lc-deny" data-tofu-action="_lcDecide(this,false)">' + escapeHtml(t('update.deny')) + '</button>' +
        '</div></div>';
    }).join('') + '</div>';
}

/** Approve (and execute) or deny one pending lifecycle request. */
async function _lcDecide(btn, approved) {
  const row = btn && btn.closest ? btn.closest('.upd-lc-row') : null;
  const id = row && row.dataset ? row.dataset.id : '';
  const action = row && row.dataset ? row.dataset.action : '';
  if (!id) return;
  btn.disabled = true;
  try {
    await Api.update.decideLifecycleApproval(id, approved);
  } catch (e) {
    showToast('⚠️', (e && e.message) || t('update.errUnknown'), '', 5000);
    btn.disabled = false;
    return;
  }
  if (!approved) {
    showToast('◐', t('update.approvalDenied'), '', 4000);
    _renderPendingLifecycleApprovals();
    return;
  }
  if (action === 'shutdown') {
    await _fireShutdown(id);
  } else {
    // The approved id rides into the standard restart flow (progress card,
    // force-confirm on running tasks, health-poll, auto-reload).
    restartServer({ approvalId: id });
  }
}

/** One health probe; on success finish, on overall timeout bail.
 *  Success requires a genuinely NEW process answered — health.ok AND a bootId
 *  that DIFFERS from the one captured before the restart. os.execv keeps the
 *  PID + start-time, so bootId is the only reliable 'different process' signal;
 *  keying on it stops the old process (still draining) from being mistaken for
 *  a completed restart. If we could not capture a pre-restart bootId, or the
 *  server is an old build that doesn't report bootId, we degrade gracefully:
 *  accept the first ok health that carries ANY bootId, else (no bootId field at
 *  all) accept ok — never worse than the old rule, and still bounded by the
 *  overall timeout. */
async function _restartCheckHealth() {
  if (_restartDone) return;
  if ((Date.now() - _restartT0) / 1000 > 80) { _restartTimeout(); return; }
  let info = null;
  try {
    info = await Api.health.info();  // parsed JSON → carries version + bootId
  } catch (e) { info = null; }
  if (!info || !info.ok) return;
  // Preferred, robust path: we know the old bootId AND the server reports one.
  if (_restartPreBootId && info.bootId) {
    if (info.bootId === _restartPreBootId) return;  // still the OLD process — keep waiting
    _restartSucceed(info.version || '', info);
    return;
  }
  // Degraded path (no pre-id captured, or old build without bootId): accept ok.
  _restartSucceed(info.version || '', info);
}

/** Classify whether the restarted process loaded DIFFERENT source than the
 *  pre-restart one, using the code fingerprint. Returns:
 *    'changed'   — post digest differs from pre → the operator's edits are live
 *    'unchanged' — identical digest → a new process, but same source as before
 *    null        — indeterminate (no pre/post digest; non-git deploy or old build)
 *  Only a confident 'changed'/'unchanged' is surfaced; null stays silent so we
 *  never make a claim the fingerprint can't support. */
function _restartCodeVerdict(info) {
  const post = info && info.codeFingerprint && info.codeFingerprint.digest;
  if (!_restartPreFingerprint || !post) return null;
  return (post === _restartPreFingerprint) ? 'unchanged' : 'changed';
}

function closeUpdateModal() {
  // A restart owns the modal: the progress card is the only feedback the user
  // has while the server is down (no live logs over the wire). Dismissing it —
  // via the × button or a backdrop click — would strand the user staring at a
  // dead page with no indication the restart is still in flight. Pin it open
  // until the restart resolves (auto-reloads on success, or shows a timeout).
  if (_restartActive) return;
  const modal = document.getElementById('updateModal');
  if (modal) modal.classList.remove('open');
  // Closing mid-apply must not read as a cancel: the download keeps running
  // server-side and the completion toast will offer the restart. Say so once.
  if (_updateBusy) {
    showToast('ℹ️', t('update.bgRunningToast'), '', 5000);
  }
}

// Boot check shortly after load (don't block first paint / chat boot).
// _onReady (feature-bridge.js, core) — NOT window 'load': a deferred module
// lands AFTER the load event fired, so a load listener would never run and
// the update check would silently never happen (Epic-E sub-9).
if (typeof window !== 'undefined') {
  _onReady(function () {
    setTimeout(_updateBootCheck, 3000);
  });
}

/* ===== migrated source: timer.js ===== */
/* ═══════════════════════════════════════════
   timer.js — Timer Watcher panel & badge
   ═══════════════════════════════════════════ */

let _timerPanelOpen = false;
let _timerPollInterval = null;
let _timerListInFlight = null;
let _timerPushWired = false;
let _timerRefreshTimer = null;
let _timerRefreshAfterFlight = false;
/* ★ In-flight row operations (pt_2bf8e5c85d8f4b2e): timerId →
 *   'cancelling' | 'triggering'. Consulted by _renderTimerList so the busy
 *   state SURVIVES the panel's 30s auto-refresh — a one-off DOM patch would
 *   be silently reverted by it. _timerLastTimers caches the last fetched rows
 *   so the pending re-render is synchronous (no refetch on the click frame). */
let _timerPending = {};
let _timerLastTimers = null;

function _timerSetPending(timerId, kind) {
  _timerPending[timerId] = kind;
  if (_timerLastTimers) _renderTimerList(_timerLastTimers);
}
function _timerClearPending(timerId, skipRender) {
  if (delete _timerPending[timerId] && !skipRender && _timerLastTimers) {
    _renderTimerList(_timerLastTimers);
  }
}

/* One list request is shared by badge, panel, push invalidation, and fallback
 * polling.  When an invalidation lands during a request, schedule exactly one
 * follow-up after it settles so a just-returned stale snapshot cannot win. */
function _fetchTimerList(summaryOnly = false) {
  if (_timerListInFlight) {
    // A full response satisfies a concurrent badge refresh too. The reverse
    // is not true: if the panel opens while a summary request is in flight,
    // promote to one full request after it settles instead of rendering the
    // missing ``timers`` array as an empty panel.
    if (summaryOnly || !_timerListInFlight.summaryOnly) {
      return _timerListInFlight.request;
    }
    return _timerListInFlight.request.then(() => _fetchTimerList(false));
  }
  const request = Promise.resolve().then(() => Api.timer.list(summaryOnly));
  _timerListInFlight = { request, summaryOnly };
  const settled = () => {
    if (!_timerListInFlight || _timerListInFlight.request !== request) return;
    _timerListInFlight = null;
    if (_timerRefreshAfterFlight) {
      _timerRefreshAfterFlight = false;
      _scheduleTimerRefresh();
    }
  };
  request.then(settled, settled);
  return request;
}

function _updateTimerBadge(data) {
  if (!data || !data.ok) return;
  const timers = Array.isArray(data.timers) ? data.timers : [];
  const hasTimers = Array.isArray(data.timers)
    ? timers.length > 0
    : !!data.has_timers;
  const activeCount = data.active_count || 0;
  const badge = document.getElementById("timerBadge");
  const countEl = document.getElementById("timerCount");
  if (badge) badge.style.display = hasTimers ? "inline-flex" : "none";
  if (countEl) {
    if (activeCount > 0) {
      countEl.textContent = activeCount;
      countEl.style.display = "inline-flex";
    } else {
      countEl.style.display = "none";
    }
  }
}

// ── Toggle panel visibility ──
function toggleTimerPanel(e) {
  const panel = document.getElementById("timerPanel");
  if (!panel) return;
  // The panel is a DOM descendant of the badge, so clicks (and the click
  // that ends a text-selection drag) inside the panel bubble up to this
  // onclick handler. Without this guard they would flip the panel shut.
  if (e && panel.contains(/** @type {Node} */ (e.target))) return;
  if (e) e.stopPropagation();
  _timerPanelOpen = !_timerPanelOpen;
  panel.classList.toggle("visible", _timerPanelOpen);
  if (_timerPanelOpen) _refreshTimerPanel();
}

// ── Refresh panel data from API ──
async function _refreshTimerPanel() {
  try {
    const data = await _fetchTimerList(false);
    if (!data || !data.ok) return;

    const timers = data.timers || [];
    const content = document.getElementById("timerPanelContent");
    _updateTimerBadge(data);

    if (!content) return;
    _timerLastTimers = timers;
    _renderTimerList(timers);
  } catch (e) {
    console.warn("[Timer] Panel refresh failed:", e);
  }
}

/* Render the panel rows from a timer list (extracted seam — the refresh
   path AND the pending re-render both ride it). Rows with an in-flight
   operation paint the busy label INSTEAD of their action buttons. */
function _renderTimerList(timers) {
  const content = document.getElementById("timerPanelContent");
  if (!content) return;

  if (timers.length === 0) {
    content.innerHTML = '<div class="timer-panel-empty">' + t('timer.empty') + '</div>';
    return;
  }

  const _jumpHint = t('timer.jumpHint');
  const _cancellingLabel = t('timer.cancelling');
  const _triggeringLabel = t('timer.triggering');
  let html = "";
  for (const t of timers) {
      const statusIcon = { active: IconDot('green'), triggered: Icon('alarm', 12), cancelled: IconDot('red'), exhausted: IconDot('grey') }[t.status] || IconDot('grey');
      const statusClass = t.status;
      const pollAt = t.last_poll_at ? new Date(t.last_poll_at).toLocaleTimeString() : "never";
      const decLabel = t.last_poll_decision ? t.last_poll_decision.toUpperCase() : "—";
      const decClass = t.last_poll_decision || "wait";
      const maxPolls = t.max_polls > 0 ? ` / ${t.max_polls}` : "";
      const checkCmd = t.check_command ? escapeHtml(t.check_command.slice(0, 60)) : "(none)";
      const created = t.created_at ? new Date(t.created_at).toLocaleString() : "?";
      const convId = t.conv_id || "";

      html += `<div class="timer-panel-item timer-status-${statusClass}">
        <div class="tpi-header${convId ? ' tpi-header-jump' : ''}" ${convId ? `data-tofu-action="_jumpToTimerConv('${convId}', event)" title="${escapeHtml(_jumpHint)}"` : ''}>
          <span class="tpi-status">${statusIcon}</span>
          <span class="tpi-id">${escapeHtml(t.id)}</span>
          <span class="tpi-status-label">${t.status}</span>
        </div>
        <div class="tpi-meta">
          ${Icon('chart', 11, 'opacity:.7')} Polls: ${t.poll_count}${maxPolls} | Interval: ${t.poll_interval}s<br>
          ${Icon('clock', 11, 'opacity:.7')} Last poll: ${pollAt} <span class="tpi-decision ${decClass}">${decLabel}</span><br>
          ${t.last_poll_reason ? `${Icon('messageCircle', 11, 'opacity:.7')} ${escapeHtml(t.last_poll_reason.slice(0, 80))}<br>` : ""}
          ${Icon('search', 11, 'opacity:.7')} Check cmd: <code>${checkCmd}</code><br>
          ${Icon('edit', 11, 'opacity:.7')} Check: ${escapeHtml((t.check_instruction || "").slice(0, 80))}${(t.check_instruction || "").length > 80 ? "…" : ""}<br>
          ${Icon('mapPin', 11, 'opacity:.7')} Conv: ${(t.conv_id || "?").slice(0, 12)}… | Created: ${created}
        </div>`;

      if (t.triggered_at) {
        html += `<div class="tpi-triggered">${Icon('alarm', 12)} Triggered: ${new Date(t.triggered_at).toLocaleString()}</div>`;
      }

      // Action buttons — replaced by the busy label while an operation
      // on THIS row is in flight (click frame → background completion).
      const _pending = _timerPending[t.id];
      if (_pending) {
        html += `<div class="tpi-actions"><span class="tpi-pending">${escapeHtml(_pending === 'cancelling' ? _cancellingLabel : _triggeringLabel)}</span></div></div>`;
      } else {
        html += `<div class="tpi-actions">
          <button data-tofu-action="_viewTimerLog('${t.id}')" class="tpi-btn tpi-btn-log" title="View poll log">${Icon('clipboard', 11)} Log</button>`;
        if (t.status === "active") {
          html += `
          <button data-tofu-action="_triggerTimer('${t.id}')" class="tpi-btn tpi-btn-trigger" title="Force trigger now">▶ Trigger</button>
          <button data-tofu-action="_cancelTimer('${t.id}')" class="tpi-btn tpi-btn-cancel" title="Cancel timer">✖ Cancel</button>`;
        }
        html += `</div></div>`;
      }
    }
    content.innerHTML = html;
}

// ── Actions ──
async function _triggerTimer(timerId) {
  /* ★ INSTANT-UI (pt_2bf8e5c85d8f4b2e): the row shows 触发中… on the CLICK
   *   frame; the POST + refresh run in the background. */
  _timerSetPending(timerId, 'triggering');
  try {
    const data = await Api.timer.trigger(timerId);
    if (data && data.ok) {
      _timerClearPending(timerId, true);   // the refresh renders the fresh state
      debugLog(`⏱️ Timer ${timerId} triggered! Execution: ${data.execution_task_id}`, "success");
      await _refreshTimerPanel();
    } else {
      _timerClearPending(timerId);       // restore the row
      debugLog(`⏱️ Trigger failed: ${data && data.error}`, "error");
    }
  } catch (e) {
    _timerClearPending(timerId);         // restore the row
    debugLog(`⏱️ Trigger error: ${e.message}`, "error");
  }
}

async function _cancelTimer(timerId) {
  /* ★ INSTANT-UI (pt_2bf8e5c85d8f4b2e): the row shows 取消中… on the CLICK
   *   frame; the POST + refresh run in the background. */
  _timerSetPending(timerId, 'cancelling');
  try {
    const data = await Api.timer.cancel(timerId);
    /* Api.timer.cancel deliberately maps HTTP failures to null so a rejected
     * request does not create an unhandled click-handler promise. Treat that
     * sentinel (and an explicit {ok:false}) as failure here; otherwise the UI
     * would announce cancellation even though the server never accepted it. */
    if (!data || data.ok === false) {
      _timerClearPending(timerId);
      debugLog(`⏱️ Cancel failed: ${data && data.error}`, "error");
      return;
    }
    _timerClearPending(timerId, true);   // the refresh renders the fresh state
    debugLog(`⏱️ Timer ${timerId} cancelled.`, "info");
    await _refreshTimerPanel();
  } catch (e) {
    _timerClearPending(timerId);         // restore the row
    debugLog(`⏱️ Cancel error: ${e.message}`, "error");
  }
}

// ── Jump to the conversation that owns a timer ──
function _jumpToTimerConv(convId, e) {
  if (e && e.stopPropagation) e.stopPropagation();
  if (!convId) return;
  // Close the panel first so the chat view is unobstructed.
  _timerPanelOpen = false;
  const panel = document.getElementById("timerPanel");
  if (panel) panel.classList.remove("visible");

  const conv = getConvById(convId);
  if (!conv) {
    if (typeof showToast === "function") {
      showToast(t('timer.convMissing'), "warning");
    }
    return;
  }
  if (typeof loadConversation === "function") loadConversation(convId);
}

// ── Show the poll log in a visible modal (was console-only) ──
async function _viewTimerLog(timerId) {
  let data;
  try {
    data = await Api.timer.status(timerId, 30);
  } catch (e) {
    debugLog(`⏱️ Log error: ${e.message}`, "error");
    if (typeof showToast === "function") showToast(t('timer.logError'), "error");
    return;
  }
  const entries = (data && data.ok && Array.isArray(data.poll_log)) ? data.poll_log : [];

  // Remove any existing log dialog before opening a new one.
  const existing = document.getElementById("_timerLogDialog");
  if (existing) existing.remove();

  let rowsHtml;
  if (entries.length === 0) {
    rowsHtml = `<div class="timer-log-empty">${escapeHtml(t('timer.logEmpty'))}</div>`;
  } else {
    rowsHtml = entries.map((entry) => {
      const time = entry.poll_time ? new Date(entry.poll_time).toLocaleString() : "?";
      const dec = entry.decision || "wait";
      const icon = dec === "ready" ? Icon('check', 12)
        : dec === "wait" ? Icon('hourglass', 12)
        : Icon('ban', 12);
      const reason = entry.reason ? escapeHtml(entry.reason) : `(${t('timer.noReason')})`;
      const tokens = entry.tokens_used != null ? `${entry.tokens_used} tok` : "";
      const model = entry.model ? ` · ${escapeHtml(entry.model)}` : "";
      const cmdOut = entry.check_output
        ? `<div class="tl-cmd">${escapeHtml(String(entry.check_output).slice(0, 600))}</div>`
        : "";
      return `<div class="timer-log-row tl-${dec}">
        <div class="tl-head">
          <span class="tl-icon">${icon}</span>
          <span class="tl-decision">${dec.toUpperCase()}</span>
          <span class="tl-time">${escapeHtml(time)}</span>
          <span class="tl-tokens">${escapeHtml(tokens)}${model}</span>
        </div>
        <div class="tl-reason">${reason}</div>
        ${cmdOut}
      </div>`;
    }).join("");
  }

  const overlay = document.createElement("div");
  overlay.id = "_timerLogDialog";
  overlay.className = "timer-log-overlay";
  overlay.innerHTML = `
    <div class="timer-log-card" role="dialog" aria-modal="true">
      <div class="timer-log-head">
        <span class="timer-log-title">${Icon('clipboard', 15, 'vertical-align:-2px')} ${escapeHtml(t('timer.logTitle'))} <code>${escapeHtml(timerId)}</code></span>
        <button class="timer-log-close" id="_timerLogClose" aria-label="close">${Icon('x', 14)}</button>
      </div>
      <div class="timer-log-body">${rowsHtml}</div>
    </div>`;
  document.body.appendChild(overlay);

  function _close() { overlay.remove(); document.removeEventListener("keydown", _onKey); }
  function _onKey(ev) { if (ev.key === "Escape") _close(); }
  document.getElementById("_timerLogClose").addEventListener("click", _close);
  overlay.addEventListener("click", (ev) => { if (ev.target === overlay) _close(); });
  document.addEventListener("keydown", _onKey);
}

function _refreshVisibleTimerUi() {
  if (typeof document !== "undefined" && document.visibilityState === "hidden") return;
  if (_timerPanelOpen) _refreshTimerPanel();
  else _refreshTimerBadge();
}

function _scheduleTimerRefresh() {
  if (_timerListInFlight) {
    _timerRefreshAfterFlight = true;
    return;
  }
  if (_timerRefreshTimer) return;
  _timerRefreshTimer = setTimeout(() => {
    _timerRefreshTimer = null;
    _refreshVisibleTimerUi();
  }, 100);
}

/* Normal path: one lightweight invalidation over the already-open push socket.
 * `progress` changes cannot alter a closed panel's badge, so they cause no DB
 * read until the panel is visible. Terminal/create changes refresh the badge. */
function _wireTimerPush() {
  if (_timerPushWired || typeof pushSubscribe !== "function") return;
  _timerPushWired = true;
  pushSubscribe("timer", "*", (frame) => {
    if (!frame || frame.type !== "timer_changed") return;
    if (frame.change === "progress" && !_timerPanelOpen) return;
    _scheduleTimerRefresh();
  });
  if (typeof pushOnReconnect === "function") {
    pushOnReconnect(_scheduleTimerRefresh);
  }
}

// ── Push-first refresh with visibility-aware polling fallback ──
function _startTimerPolling() {
  if (_timerPollInterval) return;
  _timerPollInterval = setInterval(() => {
    if (typeof document !== "undefined" && document.visibilityState === "hidden") return;
    // An open panel needs progress details. A closed panel is event-driven
    // while push is healthy and polls only when the socket is unavailable.
    if (_timerPanelOpen) _refreshTimerPanel();
    else if (typeof pushIsConnected !== "function" || !pushIsConnected()) {
      _refreshTimerBadge();
    }
  }, 30000); // every 30s
}

async function _refreshTimerBadge() {
  // Scheduler is a default (always-on) tool — the timer badge surfaces
  // whenever any timer exists, no per-conversation toggle gate.
  try {
    const data = await _fetchTimerList(true);
    if (!data || !data.ok) return;
    _updateTimerBadge(data);
  } catch (e) {
    // silent — badge refresh is best-effort
  }
}

// Allow mobile_panels.js to keep the open-flag in sync when it portals the
// panel to <body> as a bottom sheet.
if (typeof window !== "undefined") {
  runtimeScope._setTimerPanelOpen = function (v) { _timerPanelOpen = !!v; };
}

// Close panel on outside click
document.addEventListener("click", (e) => {
  if (!_timerPanelOpen) return;
  const panel = document.getElementById("timerPanel");
  // On mobile the panel is portaled out of the badge into <body>; its own
  // backdrop (mobile_panels.js) owns closing, so skip the badge-based check.
  if (panel && panel.classList.contains("mobile-panel-portaled")) return;
  const badge = document.getElementById("timerBadge");
  if (badge && !badge.contains(/** @type {Node} */ (e.target))) {
    _timerPanelOpen = false;
    if (panel) panel.classList.remove("visible");
  }
});

// Start polling on load
_wireTimerPush();
_startTimerPolling();
// Initial badge check
setTimeout(_refreshTimerBadge, 3000);

document.addEventListener("visibilitychange", () => {
  if (document.visibilityState === "visible") _scheduleTimerRefresh();
});

